    def is_chad_enabled(self) -> bool:
        var = self.__dict__.get("chad_enabled_var")
        if var is None:
            return True
        try:
            return bool(var.get())
        except Exception:
            return True

    def _ensure_chad_enabled(self, message: str = "Chad-Anbindung ist deaktiviert."):
        if self.is_chad_enabled():
            return True
        try:
            self.chad_analysis_status_var.set(
                message
                if message != "Chad-Anbindung ist deaktiviert."
                else self.tr(
                    "chad_status_disabled",
                    "Chad-Anbindung ist deaktiviert.",
                )
            )
        except Exception:
            pass
        return False

    def _show_chad_activation_required_popup(self):
        try:
            self.chad_analysis_status_var.set(
                self.tr(
                    "chad_status_activate_first",
                    "Bitte vorher Chad aktivieren.",
                )
            )
        except Exception:
            pass
        try:
            messagebox.showinfo(
                self.tr("chad_popup_disabled_title", "Chad deaktiviert"),
                self.tr("chad_status_activate_first", "Bitte vorher Chad aktivieren."),
                parent=self,
            )
        except Exception:
            pass

    def _update_chad_controls_state(self):
        enabled = self.is_chad_enabled()

        def _set_widget_state(widget, state):
            try:
                widget.configure(state=state)
            except Exception:
                pass

        _set_widget_state(
            self.__dict__.get("openai_api_key_entry"),
            "normal" if enabled else "disabled",
        )
        _set_widget_state(
            self.__dict__.get("chad_chat_input"),
            "normal" if enabled else "disabled",
        )

        button_widgets = [
            ("btn_chad_api_paste", "normal"),
            ("btn_chad_api_apply", "normal"),
            ("btn_chad_api_save", "normal" if self.keyring_available else "disabled"),
            ("btn_chad_api_clear", "normal"),
            ("btn_chad_api_delete", "normal"),
            ("btn_chad_send", "normal"),
            ("btn_chad_take_analysis", "normal"),
            ("btn_chad_import_file", "normal"),
            ("btn_chad_online", "normal"),
            ("btn_chad_copy", "normal"),
            ("btn_chad_clear", "normal"),
            ("btn_chad_top", "normal"),
            ("btn_chad_bottom", "normal"),
            ("chad_auto_scroll_check", "normal"),
        ]
        for widget_name, enabled_state in button_widgets:
            widget = self.__dict__.get(widget_name)
            if widget is None:
                continue
            _set_widget_state(widget, enabled_state if enabled else "disabled")

        if enabled:
            try:
                self.chad_chat_status_var.set(
                    self.tr("chad_status_chat_ready", "Chat bereit.")
                )
            except Exception:
                pass
        else:
            try:
                self.chad_chat_status_var.set(
                    self.tr(
                        "chad_status_chat_disabled",
                        "Chad-Anbindung deaktiviert.",
                    )
                )
                self.chad_online_status_var.set(
                    self.tr(
                        "chad_online_status_disabled",
                        "Online-Analyse: deaktiviert",
                    )
                )
                self.chad_analysis_status_var.set(
                    self.tr("chad_status_disabled", "Chad-Anbindung ist deaktiviert.")
                )
            except Exception:
                pass

    def _build_chad_analysis_prompt(self, title: str, raw_text: str) -> str:
        service = self.ai_service or AiAnalysisService()
        return service.build_prompt(title, raw_text)

    def _cancel_active_context_menu_timeout(self):
        after_id = self.__dict__.get("_active_context_menu_after_id")
        if after_id is None:
            return
        self._active_context_menu_after_id = None
        try:
            self.after_cancel(after_id)
        except Exception:
            pass

    def _close_active_context_menu(self):
        self._cancel_active_context_menu_timeout()
        menu = self.__dict__.get("_active_context_menu")
        self._active_context_menu = None
        if menu is None:
            return
        try:
            menu.unpost()
        except Exception:
            pass
        try:
            menu.grab_release()
        except Exception:
            pass

    def _schedule_active_context_menu_close(self):
        self._cancel_active_context_menu_timeout()
        self._active_context_menu_after_id = self.after(
            10000, self._close_active_context_menu
        )

    def _handle_app_click_for_context_menu(self, _event=None):
        self._close_active_context_menu()

    def _show_context_menu(self, menu, event):
        self._close_active_context_menu()
        self._active_context_menu = menu
        self._schedule_active_context_menu_close()
        try:
            menu.tk_popup(event.x_root, event.y_root)
        finally:
            try:
                menu.grab_release()
            except Exception:
                pass
        return "break"

    def _copy_text_widget_selection(self, text_widget, _event=None):
        try:
            selected = text_widget.get("sel.first", "sel.last")
        except Exception:
            return "break"
        if not selected:
            return "break"
        self.clipboard_clear()
        self.clipboard_append(selected)
        return "break"

    def _copy_listbox_selection(self, listbox, _event=None):
        try:
            selection = listbox.curselection()
        except Exception:
            selection = ()
        if not selection:
            return "break"

        lines = []
        for index in selection:
            try:
                value = listbox.get(index)
            except Exception:
                value = ""
            value = str(value or "").strip()
            if value:
                lines.append(value)

        if not lines:
            return "break"

        self.clipboard_clear()
        self.clipboard_append("\n".join(lines))
        return "break"

    def get_treeview_selection_text(self, treeview) -> str:
        try:
            selection = tuple(treeview.selection())
        except Exception:
            selection = ()
        if not selection:
            return ""

        try:
            columns = tuple(treeview["columns"])
        except Exception:
            columns = ()

        headings = []
        for column in columns:
            try:
                heading = treeview.heading(column, "text")
            except Exception:
                heading = ""
            headings.append(str(heading or column))

        lines = []
        if headings:
            lines.append("\t".join(headings))

        for item_id in selection:
            try:
                values = treeview.item(item_id, "values")
            except Exception:
                values = ()
            row = [str(value or "").strip() for value in values]
            if row:
                lines.append("\t".join(row))

        return "\n".join(lines).strip()

    def _copy_treeview_selection(self, treeview, _event=None):
        text = self.get_treeview_selection_text(treeview)
        if not text:
            return "break"
        self.clipboard_clear()
        self.clipboard_append(text)
        return "break"

    def _paste_text_widget_clipboard(self, text_widget, _event=None):
        try:
            if str(text_widget.cget("state")) == "disabled":
                return "break"
        except Exception:
            pass

        try:
            text_widget.focus_force()
        except Exception:
            pass

        try:
            text_widget.event_generate("<<Paste>>")
            return "break"
        except Exception:
            pass

        try:
            pasted = self.clipboard_get()
        except Exception:
            pasted = ""

        if pasted:
            try:
                text_widget.insert("insert", pasted)
            except Exception:
                pass
        return "break"

    def _paste_entry_widget_clipboard(self, entry_widget, _event=None):
        try:
            state = str(entry_widget.cget("state"))
            if state in {"disabled", "readonly"}:
                return "break"
        except Exception:
            pass

        try:
            entry_widget.focus_force()
        except Exception:
            pass

        try:
            entry_widget.event_generate("<<Paste>>")
            return "break"
        except Exception:
            pass

        try:
            pasted = self.clipboard_get()
        except Exception:
            pasted = ""

        if pasted:
            try:
                entry_widget.insert("insert", pasted)
            except Exception:
                pass
        return "break"

    def attach_selection_copy_shortcuts(self, widget, kind: str):
        if widget is None:
            return

        attached = self.__dict__.setdefault("_selection_copy_shortcuts_attached", set())
        widget_id = str(widget)
        if widget_id in attached:
            return
        attached.add(widget_id)

        if kind == "text":

            def handler(event):
                return self._copy_text_widget_selection(widget, event)

        elif kind == "listbox":

            def handler(event):
                return self._copy_listbox_selection(widget, event)

        elif kind == "treeview":

            def handler(event):
                return self._copy_treeview_selection(widget, event)

        else:
            return

        widget.bind("<Control-c>", handler, add="+")
        widget.bind("<Control-C>", handler, add="+")
        widget.bind("<Control-Insert>", handler, add="+")
        if kind == "text":
            widget.bind(
                "<Control-v>",
                lambda event: self._paste_text_widget_clipboard(widget, event),
                add="+",
            )
            widget.bind(
                "<Control-V>",
                lambda event: self._paste_text_widget_clipboard(widget, event),
                add="+",
            )
            widget.bind(
                "<Shift-Insert>",
                lambda event: self._paste_text_widget_clipboard(widget, event),
                add="+",
            )

    def attach_entry_edit_shortcuts(self, entry_widget):
        if entry_widget is None:
            return

        attached = self.__dict__.setdefault("_selection_copy_shortcuts_attached", set())
        widget_id = str(entry_widget)
        if widget_id in attached:
            return
        attached.add(widget_id)

        def copy_handler(_event=None):
            try:
                selected = entry_widget.selection_get()
            except Exception:
                return "break"
            if not selected:
                return "break"
            self.clipboard_clear()
            self.clipboard_append(selected)
            return "break"

        def paste_handler(event):
            return self._paste_entry_widget_clipboard(entry_widget, event)

        entry_widget.bind("<Control-c>", copy_handler, add="+")
        entry_widget.bind("<Control-C>", copy_handler, add="+")
        entry_widget.bind("<Control-Insert>", copy_handler, add="+")
        entry_widget.bind("<Control-v>", paste_handler, add="+")
        entry_widget.bind("<Control-V>", paste_handler, add="+")
        entry_widget.bind("<Shift-Insert>", paste_handler, add="+")

    def safe_attach_entry_edit_shortcuts(self, widget_name: str):
        widget = self.__dict__.get(widget_name)
        if widget is None:
            return

        try:
            self.attach_entry_edit_shortcuts(widget)
        except Exception as exc:
            try:
                self.log(
                    f"[WARN] Edit-Shortcuts für {widget_name} konnten nicht gesetzt werden: {exc}"
                )
            except Exception:
                pass

    def safe_attach_selection_copy_shortcuts(self, widget_name: str, kind: str):
        widget = self.__dict__.get(widget_name)
        if widget is None:
            return

        try:
            self.attach_selection_copy_shortcuts(widget, kind)
        except Exception as exc:
            try:
                self.log(
                    f"[WARN] Kopier-Shortcuts für {widget_name} konnten nicht gesetzt werden: {exc}"
                )
            except Exception:
                pass

