    # ---------- IPv6 ----------
    def ipv6_is_disabled(self):
        checks = [
            "net.ipv6.conf.all.disable_ipv6",
            "net.ipv6.conf.default.disable_ipv6",
        ]
        values = []

        for key in checks:
            rc, out = run_cmd(["sysctl", "-n", key], timeout=3)
            if rc == 0:
                value = (out or "").strip()
                if value in {"0", "1"}:
                    values.append(value == "1")
                    continue
            proc_path = f"/proc/sys/{key.replace('.', '/')}"
            try:
                with open(proc_path, "r", encoding="utf-8") as f:
                    value = f.read().strip()
                if value in {"0", "1"}:
                    values.append(value == "1")
            except Exception:
                continue

        if values:
            # Konservativ: IPv6 gilt als deaktiviert, wenn all/default deaktiviert sind.
            return all(values)
        return False

    def ipv6_runtime_available_on_iface(self, iface):
        name = (iface or "").strip()
        if not name or self.ipv6_is_disabled():
            return False
        rc, out = run_cmd(
            ["ip", "-6", "-o", "addr", "show", "dev", name, "scope", "global"],
            timeout=4,
        )
        if rc != 0:
            return False
        for line in (out or "").splitlines():
            if " inet6 " in line:
                return True
        return False

    def update_ipv6_controls_state(self):
        active_profile = (self.active_wg_profile() or "").strip()
        selected_profile = ""
        if hasattr(self, "isp_stealth_vpn_profile"):
            selected_profile = (self.isp_stealth_vpn_profile.get() or "").strip()
        if not selected_profile and hasattr(self, "isp_stealth_vpn_choice"):
            selected_profile = self._privacy_vpn_profile_from_value(
                self.isp_stealth_vpn_choice.get()
            )

        buttons_state = "normal"
        system_ipv6_enabled = not self.ipv6_is_disabled()
        active_iface = (self.get_wg_iface() or "").strip()
        active_supports_ipv6 = bool(
            active_profile and self.profile_supports_ipv6(active_profile)
        )
        active_runtime_ipv6 = bool(
            active_iface and self.ipv6_runtime_available_on_iface(active_iface)
        )

        if not active_profile:
            vpn_status = "kein aktives Profil"
        elif active_runtime_ipv6 or (active_iface and system_ipv6_enabled):
            vpn_status = "nutzt IPv6"
        elif active_supports_ipv6 and not system_ipv6_enabled:
            vpn_status = "erwartet IPv6, System deaktiviert"
        else:
            vpn_status = "nutzt nur IPv4"

        system_status = "aktiv" if system_ipv6_enabled else "deaktiviert"
        ipv6_hint_lines = [
            "IPv6 Status:",
            f"System:        {system_status}",
            f"VPN-Profil:    {vpn_status}",
        ]

        ipv6_hint = "\n".join(ipv6_hint_lines)

        for widget_name in ("btn_ipv6_on", "btn_ipv6_off"):
            widget = getattr(self, widget_name, None)
            if widget is None:
                continue
            try:
                widget.configure(state=buttons_state)
            except Exception:
                try:
                    widget["state"] = buttons_state
                except Exception:
                    pass

        if hasattr(self, "ipv6_controls_hint"):
            if not active_profile:
                hint_color = "#666666"
            elif active_runtime_ipv6:
                hint_color = "#2e7d32"
            else:
                hint_color = "#c62828"
            self.ipv6_controls_hint.config(text=ipv6_hint, foreground=hint_color)

        privacy_profile = active_profile or selected_profile
        privacy_enabled = True
        privacy_hint = ""
        if privacy_profile and not self.profile_supports_ipv6(privacy_profile):
            privacy_enabled = False
            if active_profile:
                privacy_hint = "Aktives VPN-Profil nutzt nur IPv4"
            else:
                privacy_hint = "Gewaehltes Privacy-VPN-Profil nutzt nur IPv4"

        privacy_state = "normal" if privacy_enabled else "disabled"
        widget = getattr(self, "cb_privacy_ipv6", None)
        if widget is not None:
            try:
                widget.configure(state=privacy_state)
            except Exception:
                try:
                    widget["state"] = privacy_state
                except Exception:
                    pass
        if hasattr(self, "privacy_ipv6_hint"):
            self.privacy_ipv6_hint.config(text=privacy_hint)

    def ipv6_disable(self, refresh_ui=True):
        ok = True
        cmds = [
            ["sudo", "-n", "sysctl", "-w", "net.ipv6.conf.all.disable_ipv6=1"],
            ["sudo", "-n", "sysctl", "-w", "net.ipv6.conf.default.disable_ipv6=1"],
            ["sudo", "-n", "sysctl", "-w", "net.ipv6.conf.lo.disable_ipv6=1"],
        ]
        for c in cmds:
            rc, out = run_cmd(c, timeout=6)
            if rc != 0:
                ok = False
                if out:
                    self.log_safe(out)
        self.log_safe("IPv6: deaktiviert (sysctl; nicht persistent nach Reboot).")
        if refresh_ui:
            self.refresh_safe()
        return ok

    def ipv6_enable(self, refresh_ui=True):
        ok = True
        cmds = [
            ["sudo", "-n", "sysctl", "-w", "net.ipv6.conf.all.disable_ipv6=0"],
            ["sudo", "-n", "sysctl", "-w", "net.ipv6.conf.default.disable_ipv6=0"],
            ["sudo", "-n", "sysctl", "-w", "net.ipv6.conf.lo.disable_ipv6=0"],
        ]
        for c in cmds:
            rc, out = run_cmd(c, timeout=6)
            if rc != 0:
                ok = False
                if out:
                    self.log_safe(out)
        self.log_safe("IPv6: aktiviert (sysctl; nicht persistent nach Reboot).")
        if refresh_ui:
            self.refresh_safe()
        return ok

    # ---------- Network detect ----------
    def get_default_iface(self):
        _, out = run_cmd(["ip", "route", "show", "default"], timeout=3)
        parts = out.split()
        for i, p in enumerate(parts):
            if p == "dev" and i + 1 < len(parts):
                return parts[i + 1]
        return "eth0"

    def nm_active_connections(self):
        _, out = run_cmd(
            ["nmcli", "-t", "-f", "NAME,DEVICE", "con", "show", "--active"], timeout=5
        )
        res = []
        for line in (out or "").splitlines():
            if ":" in line:
                n, d = line.split(":", 1)
                if n and d:
                    res.append((n, d))
        return res

    def nm_active_conn_for_dev(self, dev: str):
        for n, d in self.nm_active_connections():
            if d == dev:
                return n
        return None

    def check_internet(self):
        try:
            p = subprocess.run(
                ["ping", "-c", "1", "-W", "1", "1.1.1.1"],
                stdout=subprocess.DEVNULL,
                stderr=subprocess.DEVNULL,
                timeout=2,
                check=False,
                text=True,
            )
            return p.returncode == 0
        except Exception:
            return False

    def _internet_transition_active(self):
        if self._dns_runtime_transition_active():
            return True
        active_operation = str(self.__dict__.get("network_active_operation") or "")
        active_operation = active_operation.strip().lower()
        return bool(
            active_operation
            and any(token in active_operation for token in ("vpn", "internet", "dns"))
        )

    def _update_internet_indicator_state(self, inet_ok: bool):
        if self._internet_transition_active():
            self.__dict__["internet_indicator_state"] = "transition"
            return "transition"

        if inet_ok:
            self.__dict__["internet_fail_streak"] = 0
            self.__dict__["internet_indicator_state"] = "ok"
            return "ok"

        fail_streak = int(self.__dict__.get("internet_fail_streak", 0)) + 1
        self.__dict__["internet_fail_streak"] = fail_streak
        state = "warning" if fail_streak == 1 else "error"
        self.__dict__["internet_indicator_state"] = state
        return state

    def internet_disable(self, interactive_guard=True):
        if not self._try_begin_network_operation("Internet AUS"):
            return False
        try:
            if interactive_guard and not self._confirm_danger_action(
                "network:internet_off",
                title=self.tr("internet_off_confirm_title", "Internet AUS bestätigen"),
                prompt=self.tr(
                    "internet_off_confirm_message",
                    "Diese Aktion deaktiviert Netzwerk systemweit über NetworkManager.\n"
                    "Aktive Verbindungen werden getrennt.\n\n"
                    "Wirklich fortfahren?",
                ),
                cooldown_s=0,
                require_phrase="AUSFUEHREN",
            ):
                self.log("Internet AUS abgebrochen.")
                return False

            if not has_cmd("nmcli"):
                self.log("Internet AN/AUS nicht verfügbar: nmcli fehlt.")
                messagebox.showerror(
                    self.tr(
                        "networkmanager_missing_title",
                        "NetworkManager nicht verfügbar",
                    ),
                    self.tr(
                        "networkmanager_missing_message",
                        "nmcli (NetworkManager) ist nicht installiert.\n"
                        "Internet AN/AUS ist nicht möglich.",
                    ),
                    parent=self,
                )
                return False

            if not self.ensure_sudo_session("Internet deaktivieren"):
                return False

            state_coordinator = self._state_coordinator()
            if state_coordinator is not None:
                suspend_state = state_coordinator.capture_internet_suspend_state(
                    ufw_was_active=self.check_ufw_active(),
                    killswitch_was_active=self.killswitch_is_on(),
                    vpn_was_active=bool(self.get_wg_iface()),
                    vpn_profile=self.active_wg_profile() or "",
                    vpn_interface=self.get_wg_iface() or "",
                )
            else:
                suspend_state = {
                    "ufw_was_active": self.check_ufw_active(),
                    "killswitch_was_active": self.killswitch_is_on(),
                    "vpn_was_active": bool(self.get_wg_iface()),
                    "vpn_profile": self.active_wg_profile() or "",
                    "vpn_interface": self.get_wg_iface() or "",
                }
            self.internet_suspend_state = dict(suspend_state)
            self.log("Internet AUS: Vorzustand gespeichert.")

            if suspend_state["killswitch_was_active"]:
                self.log("Killswitch vorübergehend deaktiviert.")
                if not self.killswitch_off(
                    async_mode=False, ensure_sudo=False, refresh_ui=False
                ):
                    self.log(
                        "Internet AUS abgebrochen: Killswitch konnte nicht sicher deaktiviert werden."
                    )
                    self.internet_suspend_state = self._default_internet_suspend_state()
                    return False

            rc, out = run_cmd(["sudo", "-n", "nmcli", "networking", "off"], timeout=10)
            if rc == 0:
                self.log("Internet systemweit deaktiviert.")
                self.after(500, self.refresh)
                return True

            self.log(f"Internet AUS fehlgeschlagen: {out}")
            if suspend_state["killswitch_was_active"]:
                if self.killswitch_on(
                    async_mode=False, ensure_sudo=False, refresh_ui=False
                ):
                    self.log("Rollback: Killswitch wieder aktiviert.")
                else:
                    self.log(
                        "Rollback fehlgeschlagen: Killswitch konnte nach Internet-AUS-Fehler nicht wieder aktiviert werden."
                    )
            messagebox.showerror(
                self.tr("internet_off_failed_title", "Internet AUS fehlgeschlagen"),
                self.tr(
                    "internet_off_failed_message",
                    "Netzwerk konnte nicht deaktiviert werden:\n{details}",
                ).format(details=out),
                parent=self,
            )
            self.internet_suspend_state = self._default_internet_suspend_state()
            return False
        finally:
            self._end_network_operation()

    def internet_enable(self, interactive_guard=True):
        if interactive_guard and not self._confirm_danger_action(
            "network:internet_on",
            title=self.tr("internet_on_confirm_title", "Internet AN bestätigen"),
            prompt=self.tr(
                "internet_on_confirm_message",
                "Diese Aktion aktiviert Netzwerk systemweit über NetworkManager.\n"
                "Anschließend wird ein gespeicherter VPN/Killswitch-Zustand ggf. wiederhergestellt.\n\n"
                "Wirklich fortfahren?",
            ),
            cooldown_s=0,
            require_phrase="AUSFUEHREN",
        ):
            self.log("Internet AN abgebrochen.")
            return False

        if not has_cmd("nmcli"):
            self.log("Internet AN/AUS nicht verfügbar: nmcli fehlt.")
            messagebox.showerror(
                self.tr(
                    "networkmanager_missing_title",
                    "NetworkManager nicht verfügbar",
                ),
                self.tr(
                    "networkmanager_missing_message",
                    "nmcli (NetworkManager) ist nicht installiert.\n"
                    "Internet AN/AUS ist nicht möglich.",
                ),
                parent=self,
            )
            return False

        if not self.ensure_sudo_session("Internet aktivieren"):
            return False

        # Async ausführen, um nicht im UI zu blocken
        def job():
            self._internet_on_sync()

        self.run_async(job)
        return True

    def _default_internet_suspend_state(self):
        coordinator = self._state_coordinator()
        if coordinator is not None:
            return coordinator.default_internet_suspend_state()
        return {
            "ufw_was_active": False,
            "killswitch_was_active": False,
            "vpn_was_active": False,
            "vpn_profile": "",
            "vpn_interface": "",
        }

    def _capture_stealth_runtime_state(self):
        dns_choice_var = self.__dict__.get("dns_choice")
        dns_choice = "System (DHCP/auto)"
        if dns_choice_var is not None:
            dns_choice = (dns_choice_var.get() or "System (DHCP/auto)").strip()

        state_coordinator = self._state_coordinator()
        if state_coordinator is not None:
            return state_coordinator.capture_stealth_runtime_state(
                ipv6_was_disabled=self.ipv6_is_disabled(),
                killswitch_was_on=self.killswitch_is_on(),
                vpn_was_active=bool(self.active_wg_profile() or self.get_wg_iface()),
                vpn_profile=self.active_wg_profile() or "",
                dns_choice=dns_choice,
            )

        return {
            "ipv6_was_disabled": self.ipv6_is_disabled(),
            "killswitch_was_on": self.killswitch_is_on(),
            "vpn_was_active": bool(self.active_wg_profile() or self.get_wg_iface()),
            "vpn_profile": self.active_wg_profile() or "",
            "dns_choice": dns_choice or "System (DHCP/auto)",
        }

    def _restore_stealth_runtime_state(self, state, refresh_ui=False):
        state = state or {}
        previous_dns = (state.get("dns_choice") or "System (DHCP/auto)").strip()
        previous_vpn = (state.get("vpn_profile") or "").strip()
        previous_vpn_active = bool(state.get("vpn_was_active"))
        previous_killswitch = bool(state.get("killswitch_was_on"))
        previous_ipv6_disabled = bool(state.get("ipv6_was_disabled"))

        if not previous_killswitch and self.killswitch_is_on():
            self.killswitch_off(async_mode=False, ensure_sudo=False, refresh_ui=False)

        current_vpn_active = bool(self.active_wg_profile() or self.get_wg_iface())
        if previous_vpn_active and previous_vpn:
            if self.active_wg_profile() != self._base_wg_profile_name(previous_vpn):
                self.vpn_switch(
                    previous_vpn,
                    ensure_sudo=False,
                    refresh_ui=False,
                    force_reconnect=True,
                )
                self.wait_for_vpn_ready(timeout=12, interval=0.5)
        elif current_vpn_active:
            self.vpn_off(ensure_sudo=False, refresh_ui=False)

        if previous_ipv6_disabled:
            self.ipv6_disable(refresh_ui=False)
        else:
            self.ipv6_enable(refresh_ui=False)

        self._set_dns_choice_safe(previous_dns)
        if previous_dns in DNS_PROFILES:
            self.apply_dns(
                choice=previous_dns,
                refresh_ui=False,
                update_choice_var=False,
            )

        if previous_killswitch and not self.killswitch_is_on():
            self.killswitch_on(async_mode=False, ensure_sudo=False, refresh_ui=False)

        if refresh_ui:
            self.refresh_safe()

    def _schedule_refresh_burst(self, delays_ms=None):
        delays = delays_ms or (0, 1500, 3000)
        for delay in delays:
            self.after(delay, self.refresh)

    def _vpn_route_uses_iface(self, iface):
        name = (iface or "").strip()
        if not name:
            return False
        rc, out = run_cmd(["ip", "route", "show", "default"], timeout=3)
        if rc != 0:
            return False
        for line in (out or "").splitlines():
            if f" dev {name}" in f" {line} ":
                return True
        return False

    def _check_public_ip_quick(self):
        if not has_cmd("curl"):
            return False
        rc, out = run_cmd(
            ["curl", "-4", "-fsS", "--max-time", "3", "https://api.ipify.org"],
            timeout=4,
        )
        if rc != 0:
            return False
        ip = (out or "").strip()
        try:
            ipaddress.ip_address(ip)
            return True
        except Exception:
            return False

    def wait_for_vpn_ready(self, timeout=15, interval=0.5):
        deadline = time.time() + max(0, timeout)
        last_iface = ""
        last_internet_ok = False

        while time.time() <= deadline:
            wg_iface = str((self.get_wg_iface() or "")).strip()
            internet_ok = False
            if wg_iface:
                try:
                    internet_ok = bool(self.check_internet())
                except Exception:
                    internet_ok = False

            last_iface = wg_iface
            last_internet_ok = internet_ok

            if wg_iface and internet_ok:
                return True

            time.sleep(max(0.1, interval))

        log_debug_safe = self.__dict__.get("log_debug_safe")
        if callable(log_debug_safe):
            log_debug_safe(
                "VPN-Ready-Timeout: "
                + f"iface={'set' if last_iface else 'missing'}, "
                + f"internet_ok={last_internet_ok}"
            )
        return False

    def _internet_on_sync(self):
        if not self._try_begin_network_operation("Internet AN"):
            return False
        try:
            rc, out = run_cmd(["sudo", "-n", "nmcli", "networking", "on"], timeout=10)
            if rc != 0:
                self.after(0, lambda: self.log(f"Internet AN fehlgeschlagen: {out}"))
                self.after(
                    0,
                    lambda: messagebox.showerror(
                        self.tr(
                            "internet_on_failed_title", "Internet AN fehlgeschlagen"
                        ),
                        self.tr(
                            "internet_on_failed_message",
                            "Netzwerk konnte nicht aktiviert werden:\n{details}",
                        ).format(details=out),
                        parent=self,
                    ),
                )
                return False

            self.after(0, lambda: self.log("Internet systemweit aktiviert."))
            time.sleep(1)

            state_coordinator = self._state_coordinator()
            if state_coordinator is not None:
                suspend_state = state_coordinator.normalize_internet_suspend_state(
                    self.internet_suspend_state
                )
            else:
                suspend_state = dict(self.internet_suspend_state)
            restore_complete = True
            vpn_restore_ok = False
            if suspend_state.get("vpn_was_active"):
                restore_complete = False
                profile_to_restore = suspend_state.get("vpn_profile", "").strip()
                if profile_to_restore:
                    self.after(
                        0,
                        lambda: self.log(
                            f"VPN-Wiederherstellung gestartet (Profil: {profile_to_restore})."
                        ),
                    )
                    vpn_ok = self.vpn_switch(
                        profile_to_restore,
                        ensure_sudo=False,
                        refresh_ui=False,
                        force_reconnect=True,
                    )
                    ready_ok = self.wait_for_vpn_ready() if vpn_ok else False
                    if vpn_ok and ready_ok:
                        vpn_restore_ok = True
                        restore_complete = True
                        self.after(0, lambda: self.log("VPN-Tunnel ist bereit."))
                    else:
                        self.after(
                            0, lambda: self.log("VPN-Wiederherstellung fehlgeschlagen.")
                        )
                        if not vpn_ok:
                            self.after(
                                0,
                                lambda: self.log_debug_safe(
                                    "VPN-Wiederherstellung: Reconnect-Aufruf fehlgeschlagen."
                                ),
                            )
                        elif not ready_ok:
                            self.after(
                                0,
                                lambda: self.log_debug_safe(
                                    "VPN-Wiederherstellung: Tunnel wurde innerhalb des Zeitlimits nicht bereit."
                                ),
                            )

            if suspend_state.get("killswitch_was_active"):
                if vpn_restore_ok or not suspend_state.get("vpn_was_active"):
                    if self.killswitch_on(
                        async_mode=False, ensure_sudo=False, refresh_ui=False
                    ):
                        self.after(0, lambda: self.log("Killswitch wieder aktiviert."))
                    else:
                        restore_complete = False
                        self.after(
                            0,
                            lambda: self.log(
                                "Killswitch konnte nach VPN-Wiederherstellung nicht wieder aktiviert werden."
                            ),
                        )
                else:
                    restore_complete = False
                    self.after(
                        0,
                        lambda: self.log(
                            "Killswitch bleibt aus, damit Internetzugang nicht blockiert wird."
                        ),
                    )

            if state_coordinator is not None:
                self.internet_suspend_state = (
                    state_coordinator.finalize_internet_restore_state(
                        suspend_state,
                        restore_complete,
                    )
                )
            elif restore_complete:
                self.internet_suspend_state = self._default_internet_suspend_state()
            else:
                self.internet_suspend_state = suspend_state

            if not restore_complete:
                self.after(
                    0,
                    lambda: self.log(
                        "Wiederherstellungszustand bleibt gespeichert, damit der Restore erneut versucht werden kann."
                    ),
                )
            self._schedule_refresh_burst()
            return True
        finally:
            self._end_network_operation()

    def _is_internal_ipv4_profile(self, profile_name):
        name = (profile_name or "").strip()
        return bool(name) and name.endswith(WG_IPV4_PROFILE_SUFFIX)

    def _base_wg_profile_name(self, profile_name):
        name = (profile_name or "").strip()
        if self._is_internal_ipv4_profile(name):
            return name[: -len(WG_IPV4_PROFILE_SUFFIX)]
        return name

    def resolve_real_interface(self, profile_name):
        raw = (profile_name or "").strip()
        base = self._base_wg_profile_name(raw)
        real_iface = (base or raw).strip()
        if profile_name:
            self.log_debug(
                f"[DEBUG] Profil {profile_name} -> reales Interface: {real_iface or '-'}"
            )
        return real_iface

    def _wg_profile_path(self, profile_name):
        name = (profile_name or "").strip()
        if not name:
            return ""
        return f"/etc/wireguard/{name}.conf"

    def _wg_profile_exists(self, profile_name):
        path = self._wg_profile_path(profile_name)
        if not path:
            return False

        user_exists = os.path.isfile(path)
        if user_exists:
            self.log_debug(f"os.path.isfile({path}) = True")
            return True
        self.log_debug(f"os.path.isfile({path}) = False")

        rc, out = run_cmd(["sudo", "-n", "test", "-f", path], timeout=5)
        self.log_debug(f"sudo test -f {path} rc={rc}, out={out!r}")
        return rc == 0

    def active_wg_profile(self):
        ifaces = self.get_wg_interfaces()
        if ifaces:
            return self._base_wg_profile_name(ifaces[0])
        return None

    def get_wg_interfaces(self):
        _, out = run_cmd(["wg", "show", "interfaces"], timeout=3)
        return [p for p in out.split() if p]

    def get_wg_iface(self):
        ifaces = self.get_wg_interfaces()
        if not ifaces:
            return None
        return ifaces[0]

    def _list_wg_profile_files(self, include_internal=False):
        profiles = set()
        cmd = [
            "find",
            "/etc/wireguard",
            "-maxdepth",
            "1",
            "-type",
            "f",
            "-name",
            "*.conf",
            "-printf",
            "%f\n",
        ]
        rc, out = run_cmd(["sudo", "-n", *cmd], timeout=5)
        if rc != 0:
            rc, out = run_cmd(cmd, timeout=5)
        if rc != 0:
            return []
        for line in (out or "").splitlines():
            name = line.strip()
            if name.endswith(".conf"):
                name = name[:-5]
            if not name:
                continue
            if self._is_internal_ipv4_profile(name):
                if include_internal:
                    profiles.add(name)
                continue
            profiles.add(name)
        return sorted(profiles)

    def _read_wg_profile_text(self, profile_name):
        path = self._wg_profile_path(profile_name)
        if not path:
            return 1, ""
        rc, out = run_cmd(["sudo", "-n", "cat", path], timeout=5)
        if rc != 0:
            rc, out = run_cmd(["cat", path], timeout=5)
        return rc, out

    def parse_vpn_endpoint(self, profile_name):
        if not profile_name:
            return None, None

        rc, out = self._read_wg_profile_text(profile_name)
        if rc != 0:
            return None, None

        for raw_line in (out or "").splitlines():
            line = raw_line.split("#", 1)[0].split(";", 1)[0].strip()
            if not line or "=" not in line:
                continue
            key, value = [part.strip() for part in line.split("=", 1)]
            if key.lower() != "endpoint" or not value:
                continue

            if value.startswith("[") and "]:" in value:
                host, port = value[1:].split("]:", 1)
            else:
                host, sep, port = value.rpartition(":")
                if not sep:
                    continue

            host = host.strip()
            port = port.strip()
            if not host or not port.isdigit():
                continue
            return host, port

        return None, None

    def profile_supports_ipv6(self, profile_name):
        if not profile_name:
            return False

        rc, out = self._read_wg_profile_text(profile_name)
        if rc != 0:
            return False

        def has_ipv6_token(token):
            value = (token or "").strip()
            if not value:
                return False
            if value.startswith("[") and value.endswith("]"):
                value = value[1:-1].strip()
            try:
                if "/" in value:
                    return ipaddress.ip_network(value, strict=False).version == 6
                return ipaddress.ip_address(value).version == 6
            except ValueError:
                return False

        for raw_line in (out or "").splitlines():
            line = raw_line.split("#", 1)[0].split(";", 1)[0].strip()
            if not line or "=" not in line:
                continue
            key, value = [part.strip() for part in line.split("=", 1)]
            key_l = key.lower()
            if not value:
                continue

            if key_l in {"address", "dns", "allowedips"}:
                tokens = [part.strip() for part in value.split(",") if part.strip()]
                if any(has_ipv6_token(token) for token in tokens):
                    return True
                continue

            if key_l == "endpoint":
                host = value
                if value.startswith("[") and "]:" in value:
                    host = value[1:].split("]:", 1)[0].strip()
                else:
                    host, sep, port = value.rpartition(":")
                    if sep and port.strip().isdigit():
                        host = host.strip()
                if has_ipv6_token(host):
                    return True

        return False

    def _extract_ipv4_tokens(self, value):
        tokens = []
        for raw_token in (value or "").split(","):
            token = raw_token.strip()
            if not token:
                continue
            candidate = token
            if candidate.startswith("[") and candidate.endswith("]"):
                candidate = candidate[1:-1].strip()
            try:
                if "/" in candidate:
                    if ipaddress.ip_network(candidate, strict=False).version == 4:
                        tokens.append(token)
                elif ipaddress.ip_address(candidate).version == 4:
                    tokens.append(token)
            except ValueError:
                continue
        return tokens

    def _endpoint_uses_ipv6_literal(self, value):
        endpoint = (value or "").strip()
        if not endpoint:
            return False
        if endpoint.startswith("[") and "]:" in endpoint:
            return True
        host, sep, port = endpoint.rpartition(":")
        if not sep or not port.strip().isdigit():
            return False
        host = host.strip()
        try:
            return ipaddress.ip_address(host).version == 6
        except ValueError:
            return False

    def build_ipv4_only_wg_profile_content(self, profile_name):
        rc, out = self._read_wg_profile_text(profile_name)
        if rc != 0:
            return "", "WireGuard-Profil konnte nicht gelesen werden."

        filtered_lines = []
        relevant_keys = {"address", "dns", "allowedips"}

        for raw_line in (out or "").splitlines():
            stripped = raw_line.strip()
            if not stripped:
                filtered_lines.append("")
                continue
            if stripped.startswith("[") and stripped.endswith("]"):
                filtered_lines.append(stripped)
                continue
            if "=" not in raw_line:
                filtered_lines.append(raw_line.rstrip())
                continue

            key, value = [part.strip() for part in raw_line.split("=", 1)]
            key_l = key.lower()

            if key_l in relevant_keys:
                ipv4_tokens = self._extract_ipv4_tokens(value)
                if not ipv4_tokens:
                    continue
                filtered_lines.append(f"{key} = {', '.join(ipv4_tokens)}")
                continue

            if key_l == "endpoint" and self._endpoint_uses_ipv6_literal(value):
                return (
                    "",
                    "Endpoint nutzt eine IPv6-Adresse und kann nicht als IPv4-only Kopie übernommen werden.",
                )

            filtered_lines.append(raw_line.rstrip())

        content = "\n".join(filtered_lines).strip() + "\n"
        return content, ""

    def ensure_internal_ipv4_profile(self, profile_name, log_failures=True):
        base_profile = self._base_wg_profile_name(profile_name)
        if not base_profile:
            return False

        ipv4_profile = f"{base_profile}{WG_IPV4_PROFILE_SUFFIX}"
        if self._wg_profile_exists(ipv4_profile):
            return True

        content, reason = self.build_ipv4_only_wg_profile_content(base_profile)
        if not content:
            if log_failures and reason:
                self.log_safe(reason)
            return False

        tmp_path = ""
        try:
            with tempfile.NamedTemporaryFile(
                mode="w", encoding="utf-8", delete=False
            ) as temp_file:
                temp_file.write(content)
                tmp_path = temp_file.name
            target = self._wg_profile_path(ipv4_profile)
            rc, out = run_cmd(
                ["sudo", "-n", "install", "-m", "600", tmp_path, target],
                timeout=12,
            )
            if rc != 0:
                if log_failures:
                    self.log_safe(
                        (out or "").strip()
                        or f"Interne IPv4-Kopie konnte nicht erstellt werden: {ipv4_profile}"
                    )
                return False
            return True
        finally:
            if tmp_path:
                try:
                    os.remove(tmp_path)
                except Exception:
                    pass

    def sync_internal_ipv4_profiles(self, log_failures=True):
        # Architektur vereinfacht: kein __ipv4-Sync mehr notwendig.
        self.log_debug("[DEBUG] __ipv4-Sync deaktiviert (ein Profil = ein Interface).")

    def resolve_profile_family_runtime(self, profile_name, log_missing=True):
        base_profile = self._base_wg_profile_name(profile_name)
        system_ipv6_disabled = self.ipv6_is_disabled()
        ipv4_profile = f"{base_profile}{WG_IPV4_PROFILE_SUFFIX}" if base_profile else ""
        runtime = {
            "base_profile": base_profile,
            "ipv4_profile": ipv4_profile or base_profile,
            "effective_ipv4_interface": "",
            "effective_ipv6_interface": None,
            "supports_ipv6": (
                self.profile_supports_ipv6(base_profile) if base_profile else False
            ),
            "runtime_profile": "",
            "system_ipv6_disabled": system_ipv6_disabled,
            "endpoint_profiles": [],
        }
        if not base_profile:
            return runtime

        base_exists = self._wg_profile_exists(base_profile)
        ipv4_exists = bool(ipv4_profile and self._wg_profile_exists(ipv4_profile))
        if system_ipv6_disabled and not ipv4_exists:
            ipv4_exists = self.ensure_internal_ipv4_profile(
                base_profile,
                log_failures=log_missing,
            )
        if base_exists:
            runtime["effective_ipv4_interface"] = base_profile
            runtime["runtime_profile"] = base_profile
            runtime["endpoint_profiles"] = [base_profile]
        if ipv4_exists:
            runtime["ipv4_profile"] = ipv4_profile
            if system_ipv6_disabled:
                runtime["effective_ipv4_interface"] = ipv4_profile
                runtime["runtime_profile"] = ipv4_profile
            if ipv4_profile not in runtime["endpoint_profiles"]:
                runtime["endpoint_profiles"].append(ipv4_profile)

        self.log_debug(
            f"[DEBUG] Resolver {base_profile} -> IPv4={runtime['effective_ipv4_interface'] or '-'}, "
            f"IPv6={runtime['effective_ipv6_interface'] or 'None'}, supports_ipv6={runtime['supports_ipv6']}"
        )
        return runtime

    def resolve_runtime_vpn_profile(self, profile_name, log_missing=True):
        base_profile = self._base_wg_profile_name(profile_name)
        if not base_profile:
            return ""
        if self.ipv6_is_disabled():
            ipv4_profile = f"{base_profile}{WG_IPV4_PROFILE_SUFFIX}"
            if self._wg_profile_exists(ipv4_profile):
                return ipv4_profile
            if self.ensure_internal_ipv4_profile(
                base_profile,
                log_failures=log_missing,
            ) and self._wg_profile_exists(ipv4_profile):
                return ipv4_profile
            if log_missing:
                self.log_safe(
                    f"VPN Start abgebrochen: Fuer Profil '{base_profile}' ist keine interne IPv4-only Kopie verfuegbar."
                )
                self.log_safe(
                    "Bitte IPv6 aktivieren oder ein Profil mit nutzbaren IPv4-Eintraegen verwenden."
                )
            return ""
        if self._wg_profile_exists(base_profile):
            return base_profile
        if log_missing:
            self.log_safe(
                f"VPN Start abgebrochen: Profil '{base_profile}' nicht gefunden."
            )
        return ""

    def get_killswitch_vpn_profiles(self):
        profiles = []
        seen = set()
        candidates = [self.active_wg_profile(), *self.list_wg_profiles()]
        for profile in candidates:
            name = (profile or "").strip()
            if not name or name in seen:
                continue
            endpoint_ip, endpoint_port = self.parse_vpn_endpoint(name)
            if endpoint_ip and endpoint_port:
                seen.add(name)
                profiles.append(name)
        return profiles

    def get_killswitch_vpn_endpoints(self):
        endpoints = []
        seen = set()
        for profile in self.get_killswitch_vpn_profiles():
            endpoint_ip, endpoint_port = self.parse_vpn_endpoint(profile)
            key = (endpoint_ip, endpoint_port)
            if not endpoint_ip or not endpoint_port or key in seen:
                continue
            seen.add(key)
            endpoints.append(key)
        return endpoints

    def list_wg_profiles(self):
        profiles = set()
        for default_profile in (VPN_CH, VPN_DE):
            if self._wg_profile_exists(default_profile):
                profiles.add(default_profile)
        for name in self._list_wg_profile_files(include_internal=False):
            profiles.add(name)
        for iface in self.get_wg_interfaces():
            profiles.add(self._base_wg_profile_name(iface))
        return sorted(profile for profile in profiles if profile)

    def refresh_wg_profiles(self):
        profiles = self.list_wg_profiles()
        self.wg_profiles = profiles

    def reload_wg_profiles(self):
        self.sync_internal_ipv4_profiles(log_failures=False)
        self.refresh_wg_profiles()
        if hasattr(self, "vpn_profile_combo"):
            self.vpn_profile_combo["values"] = self.wg_profiles
        self.sync_primary_vpn_form_selection()
        self.sync_vpn_profile_form_selection()
        self.update_vpn_slot_buttons()
        self.update_primary_vpn_form_controls()
        self.refresh_vpn_slots_table()
        if hasattr(self, "isp_stealth_vpn_combo"):
            self.update_privacy_vpn_combo()

        self.update_ipv6_controls_state()
        if self.wg_profiles:
            self.log(f"WireGuard-Profile: {', '.join(self.wg_profiles)}")
        else:
            self.log("WireGuard-Profile: keine gefunden")

    def import_wg_profiles_from_folder(self):
        initialdir = self.get_wg_import_dir() or os.path.expanduser("~")
        files = filedialog.askopenfilenames(
            title="WireGuard-Profile auswählen",
            initialdir=initialdir,
            filetypes=[("WireGuard config", "*.conf"), ("Alle Dateien", "*.*")],
        )
        if not files:
            self.log("Import abgebrochen.")
            return

        first_dir = os.path.dirname(str(files[0]).strip()) if files else ""
        if first_dir:
            self.set_wg_import_dir(first_dir)

        def job():
            selected_files = sorted([str(p).strip() for p in files if str(p).strip()])

            imported = 0
            skipped = 0
            failed = 0
            imported_profiles = []

            for src in selected_files:
                base = os.path.basename(src)
                name = base[:-5] if base.endswith(".conf") else base
                if not re.match(r"^[A-Za-z0-9_.-]+$", name):
                    skipped += 1
                    self.after(
                        0,
                        lambda n=name: self.log(
                            f"Übersprungen (ungültiger Profilname): {n}"
                        ),
                    )
                    continue

                target = f"/etc/wireguard/{name}.conf"
                rc_cp, out_cp = run_cmd(
                    ["sudo", "-n", "install", "-m", "600", src, target], timeout=10
                )
                if rc_cp == 0:
                    imported += 1
                    imported_profiles.append(name)
                    self.after(0, lambda n=name: self.log(f"Profil importiert: {n}"))
                else:
                    failed += 1
                    self.after(
                        0,
                        lambda n=name, o=out_cp: self.log(
                            f"Import fehlgeschlagen ({n}): {o}"
                        ),
                    )

            def finish():
                if imported_profiles:
                    self.reconcile_vpn_slot_firewall_state(
                        reason="Import-Reconcile",
                        touched_profiles=imported_profiles,
                        refresh_ui=False,
                    )
                self.sync_internal_ipv4_profiles(log_failures=False)
                self.refresh_wg_profiles()
                if hasattr(self, "vpn_profile_combo"):
                    self.vpn_profile_combo["values"] = self.wg_profiles
                self.update_primary_vpn_form_controls()
                self.sync_primary_vpn_form_selection()
                self.sync_vpn_profile_form_selection()
                self.update_vpn_slot_buttons()
                self.refresh_vpn_slots_table()
                self.log(
                    f"WireGuard-Import beendet: {imported} importiert, {skipped} übersprungen, {failed} fehlgeschlagen."
                )

            self.after(0, finish)

        threading.Thread(target=job, daemon=True).start()

    # ---------- UFW status robust + LOCK ----------
    def _read_ufw_status(self, verbose=False):
        cmd = ["sudo", "-n", "ufw", "status"]
        if verbose:
            cmd.append("verbose")
        return run_cmd(cmd, timeout=12 if verbose else 8)

    def _ufw_status_is_active(self, status_text):
        t = (status_text or "").strip().lower()
        if "inactive" in t or "inaktiv" in t:
            return False
        if "status:" in t and ("active" in t or "aktiv" in t):
            return True
        if "status:" in t and ("inactive" not in t) and ("inaktiv" not in t):
            return True
        return False

    def _ufw_rule_lines(self, status_text):
        lines = []
        for line in (status_text or "").splitlines():
            line_l = line.strip().lower()
            if not line_l:
                continue
            if line_l.startswith(("status:", "to", "--", "action", "from")):
                continue
            if line_l.startswith(("default:", "voreinstellung:")):
                continue
            lines.append(line_l)
        return lines

    def _ufw_default_policy_matches(self, status_text, incoming=None, outgoing=None):
        t = (status_text or "").lower()
        if (
            incoming == "deny"
            and "deny (incoming)" not in t
            and "deny (eingehend)" not in t
        ):
            return False
        if (
            outgoing == "deny"
            and "deny (outgoing)" not in t
            and "deny (abgehend)" not in t
        ):
            return False
        if (
            outgoing == "allow"
            and "allow (outgoing)" not in t
            and "allow (abgehend)" not in t
        ):
            return False
        return True

    def _ufw_has_interface_rule(self, status_text, iface, direction):
        iface = (iface or "").strip().lower()
        direction = direction.strip().lower()
        if not iface or direction not in {"in", "out"}:
            return False
        for line in self._ufw_rule_lines(status_text):
            if (
                "allow" not in line and "zulassen" not in line
            ) or f"on {iface}" not in line:
                continue
            if re.search(rf"\b{direction}\b", line):
                return True
        return False

    def _ufw_has_endpoint_rule(self, status_text, endpoint_ip, endpoint_port):
        endpoint_ip = str(endpoint_ip or "").strip().lower()
        endpoint_port = str(endpoint_port or "").strip().lower()
        if not endpoint_ip or not endpoint_port:
            return False
        for line in self._ufw_rule_lines(status_text):
            if "allow" not in line and "zulassen" not in line:
                continue
            if endpoint_ip not in line or endpoint_port not in line:
                continue
            if "udp" not in line:
                continue
            if re.search(r"\bout\b", line):
                return True
        return False

    def _ufw_existing_rule_keys(self, status_text):
        keys = set()
        for raw_line in (status_text or "").splitlines():
            parsed = self._parse_ufw_structured_rule(raw_line)
            if not parsed:
                continue
            policy = (parsed.get("policy") or "").upper()
            direction = (parsed.get("direction") or "").upper()
            if policy != "ALLOW":
                continue

            iface = (parsed.get("interface") or "").strip().lower()
            if iface and direction in {"IN", "OUT"}:
                keys.add(("iface", direction.lower(), iface))

            ip = (parsed.get("ip") or "").strip().lower()
            port = str(parsed.get("port") or "").strip().lower()
            proto = (parsed.get("proto") or "").strip().lower()
            if direction == "OUT" and proto == "udp" and ip and port:
                keys.add(("endpoint", ip, port))

        return keys

    def ensure_ufw_rule_exists(
        self,
        rule,
        *,
        network_service=None,
        known_keys=None,
    ):
        rule_type = (rule or {}).get("type")
        known_keys = known_keys if isinstance(known_keys, set) else set()

        if rule_type == "interface":
            iface = str((rule or {}).get("iface") or "").strip()
            direction = str((rule or {}).get("direction") or "").strip().lower()
            if not iface or direction not in {"in", "out"}:
                return False, False, "ungültige Interface-Regel", known_keys
            key = ("iface", direction, iface.lower())
            if key in known_keys:
                return True, False, "exists", known_keys
            if network_service is not None:
                rc_cmd, out_cmd = network_service.ufw_allow_on_iface(
                    direction, iface, timeout=20
                )
            else:
                rc_cmd, out_cmd = run_cmd(
                    ["sudo", "-n", "ufw", "allow", direction, "on", iface],
                    timeout=20,
                )
            if rc_cmd == 0:
                known_keys.add(key)
                return True, True, "added", known_keys
            return False, False, (out_cmd or "").strip() or "unknown", known_keys

        if rule_type == "endpoint":
            ip = str((rule or {}).get("ip") or "").strip()
            port = str((rule or {}).get("port") or "").strip()
            if not ip or not port:
                return False, False, "ungültige Endpoint-Regel", known_keys
            key = ("endpoint", ip.lower(), port.lower())
            if key in known_keys:
                return True, False, "exists", known_keys
            if network_service is not None:
                rc_cmd, out_cmd = network_service.ufw_allow_udp_endpoint(
                    ip, port, timeout=20
                )
            else:
                rc_cmd, out_cmd = run_cmd(
                    [
                        "sudo",
                        "-n",
                        "ufw",
                        "allow",
                        "out",
                        "to",
                        ip,
                        "port",
                        port,
                        "proto",
                        "udp",
                    ],
                    timeout=20,
                )
            if rc_cmd == 0:
                known_keys.add(key)
                return True, True, "added", known_keys
            return False, False, (out_cmd or "").strip() or "unknown", known_keys

        return False, False, "unbekannter Regeltyp", known_keys

    def _parse_ufw_status_numbered(self, status_numbered_text):
        entries = []
        for raw in (status_numbered_text or "").splitlines():
            line = raw.strip()
            m = re.match(r"^\[\s*(\d+)\]\s+(.*)$", line)
            if not m:
                continue
            try:
                num = int(m.group(1))
            except ValueError:
                continue
            entries.append((num, m.group(2).strip()))
        return entries

    def _dedupe_vpn_ufw_rules(self):
        """Entfernt doppelte VPN-bezogene UFW-ALLOW-Regeln (Interface/UDP-Endpoint)."""
        rc, out = run_cmd(["sudo", "-n", "ufw", "status", "numbered"], timeout=12)
        if rc != 0 or not (out or "").strip():
            return 0

        parsed_entries = []
        for num, rest in self._parse_ufw_status_numbered(out):
            parsed = self._parse_ufw_structured_rule(rest)
            if not parsed:
                continue
            if (parsed.get("policy") or "").upper() != "ALLOW":
                continue
            category = parsed.get("category")
            if category not in {"interface", "vpn_endpoint"}:
                continue

            key = (
                (parsed.get("policy") or "").upper(),
                (parsed.get("direction") or "").upper(),
                bool(parsed.get("is_ipv6")),
                category,
                (parsed.get("interface") or "").strip().lower(),
                (parsed.get("ip") or "").strip().lower(),
                str(parsed.get("port") or "").strip().lower(),
                (parsed.get("proto") or "").strip().lower(),
                (parsed.get("to") or "").strip().lower(),
                (parsed.get("from") or "").strip().lower(),
            )
            parsed_entries.append((num, key, parsed))

        buckets = {}
        for num, key, parsed in parsed_entries:
            buckets.setdefault(key, []).append((num, parsed))

        delete_nums = []
        for items in buckets.values():
            if len(items) <= 1:
                continue
            items_sorted = sorted(items, key=lambda x: x[0])
            # älteste Regel behalten, neuere Duplikate entfernen
            for num, _parsed in items_sorted[1:]:
                delete_nums.append(num)

        if not delete_nums:
            return 0

        removed = 0
        for num in sorted(set(delete_nums), reverse=True):
            rc_del, _out_del = run_cmd(
                ["sudo", "-n", "ufw", "--force", "delete", str(num)],
                timeout=12,
            )
            if rc_del == 0:
                removed += 1

        return removed

    def _ufw_has_outgoing_port_rule(self, status_text, port, proto):
        port = str(port or "").strip()
        proto = str(proto or "").strip().lower()
        if not port or not proto:
            return False
        for line in self._ufw_rule_lines(status_text):
            if "allow" not in line and "zulassen" not in line:
                continue
            if not re.search(r"\bout\b", line):
                continue
            if proto not in line:
                continue
            if re.search(rf"\b{re.escape(port)}(?:/{re.escape(proto)})?\b", line):
                return True
        return False

    def _verify_killswitch_rules(
        self, status_text, enabled, wg_ifaces=None, handshake_rules=None
    ):
        wg_ifaces = sorted(
            {str(iface).strip() for iface in (wg_ifaces or []) if str(iface).strip()}
        )
        handshake_rules = sorted(
            {
                (str(ip).strip(), str(port).strip())
                for ip, port in (handshake_rules or [])
                if str(ip).strip() and str(port).strip()
            }
        )
        issues = []

        if not self._ufw_status_is_active(status_text):
            issues.append("UFW ist nicht aktiv.")
            return False, issues

        if enabled:
            if not self._ufw_default_policy_matches(
                status_text, incoming="deny", outgoing="deny"
            ):
                issues.append("UFW Default-Policy ist nicht auf deny/deny gesetzt.")
            if not self._ufw_has_interface_rule(status_text, "lo", "in"):
                issues.append("Loopback-IN-Regel fehlt.")
            if not self._ufw_has_interface_rule(status_text, "lo", "out"):
                issues.append("Loopback-OUT-Regel fehlt.")
            if not wg_ifaces and not handshake_rules:
                issues.append(
                    "Weder WireGuard-Interface noch Handshake-Regel vorhanden."
                )
            for wg_if in wg_ifaces:
                if not self._ufw_has_interface_rule(status_text, wg_if, "in"):
                    issues.append(f"WireGuard-IN-Regel fehlt fuer {wg_if}.")
                if not self._ufw_has_interface_rule(status_text, wg_if, "out"):
                    issues.append(f"WireGuard-OUT-Regel fehlt fuer {wg_if}.")
            for endpoint_ip, endpoint_port in handshake_rules:
                if not self._ufw_has_endpoint_rule(
                    status_text, endpoint_ip, endpoint_port
                ):
                    issues.append(
                        f"Handshake-Regel fehlt fuer {endpoint_ip}:{endpoint_port}/udp."
                    )

            return not issues, issues

        if not self._ufw_default_policy_matches(
            status_text, incoming="deny", outgoing="allow"
        ):
            issues.append("UFW Default-Policy ist nicht auf deny/allow zurueckgesetzt.")
        if self._ufw_has_interface_rule(status_text, "lo", "in"):
            issues.append("Loopback-IN-Regel ist noch vorhanden.")
        if self._ufw_has_interface_rule(status_text, "lo", "out"):
            issues.append("Loopback-OUT-Regel ist noch vorhanden.")
        for wg_if in wg_ifaces:
            if self._ufw_has_interface_rule(status_text, wg_if, "in"):
                issues.append(f"WireGuard-IN-Regel fuer {wg_if} ist noch vorhanden.")
            if self._ufw_has_interface_rule(status_text, wg_if, "out"):
                issues.append(f"WireGuard-OUT-Regel fuer {wg_if} ist noch vorhanden.")
        for endpoint_ip, endpoint_port in handshake_rules:
            if self._ufw_has_endpoint_rule(status_text, endpoint_ip, endpoint_port):
                issues.append(
                    f"Handshake-Regel fuer {endpoint_ip}:{endpoint_port}/udp ist noch vorhanden."
                )
        return not issues, issues

    def check_ufw_active(self):
        with self.ufw_lock:
            rc, out = self._read_ufw_status()
        if rc != 0:
            return False
        return self._ufw_status_is_active(out)

    def check_ssh_rule_active(self):
        with self.ufw_lock:
            rc, out = self._read_ufw_status()
        if rc != 0:
            return None
        if not self._ufw_status_is_active(out):
            return None

        ssh_patterns = (
            r"(^|\s)22/tcp(\s|$)",
            r"(^|\s)ssh(\s|$)",
        )
        for line in self._ufw_rule_lines(out):
            if "allow" not in line and "zulassen" not in line:
                continue
            if any(re.search(pattern, line, re.IGNORECASE) for pattern in ssh_patterns):
                return True
        return False

    def killswitch_is_on(self):
        wg_ifaces = sorted(set(self.get_wg_interfaces()))
        handshake_rules = self.get_killswitch_vpn_endpoints()
        with self.ufw_lock:
            rc, out = self._read_ufw_status(verbose=True)

        if rc != 0:
            return False

        verified, _issues = self._verify_killswitch_rules(
            out,
            enabled=True,
            wg_ifaces=wg_ifaces,
            handshake_rules=handshake_rules,
        )
        return verified

    # ---------- NM DNS header ----------
    def nm_get_dns_list(self, iface: str):
        _, out = run_cmd(["nmcli", "-g", "IP4.DNS", "dev", "show", iface], timeout=5)
        if not out.strip():
            return []
        return [ln.strip() for ln in out.splitlines() if ln.strip()]

    def update_dns_header(self):
        iface = self.get_default_iface()
        dns = self.nm_get_dns_list(iface) if has_cmd("nmcli") else []
        v6 = "IPv6 AUS" if self.ipv6_is_disabled() else "IPv6 AN"
        if dns:
            self.nm_dns_header_text = (
                f"NM DNS ({iface}): " + ", ".join(dns) + f" | {v6}"
            )
        else:
            self.nm_dns_header_text = f"NM DNS ({iface}): – | {v6}"
        self.dns_header.config(text=self.nm_dns_header_text)

    # ---------- WG RX/TX ----------
    def read_wg_transfer(self):
        res = {}
        rc, out = run_cmd(["sudo", "-n", "wg", "show", "all", "transfer"], timeout=6)
        if out.strip() and rc == 0:
            for line in out.splitlines():
                parts = line.strip().split()
                if len(parts) >= 3:
                    iface = parts[0]
                    try:
                        rx = int(parts[1])
                        tx = int(parts[2])
                        res[iface] = (rx, tx)
                    except ValueError:
                        pass
        if res:
            return res

        wg_if = self.get_wg_iface()
        if not wg_if:
            return {}

        rc, out = run_cmd(["sudo", "-n", "wg", "show", wg_if, "transfer"], timeout=6)
        total_rx = 0
        total_tx = 0
        if out.strip() and rc == 0:
            for line in out.splitlines():
                parts = line.strip().split()
                if len(parts) >= 3:
                    try:
                        rx = int(parts[1])
                        tx = int(parts[2])
                        total_rx += rx
                        total_tx += tx
                    except ValueError:
                        pass
            res[wg_if] = (total_rx, total_tx)
        return res

    def update_wg_rates(self):
        now = time.time()
        transfer = self.read_wg_transfer()
        wg_if = self.get_wg_iface()

        if not wg_if or wg_if not in transfer:
            self.wg_rx_rate = 0.0
            self.wg_tx_rate = 0.0
            self.last_wg_transfer = transfer
            self.last_wg_ts = now
            return wg_if, None

        cur_rx, cur_tx = transfer[wg_if]

        if (
            self.last_wg_transfer is None
            or self.last_wg_ts is None
            or wg_if not in self.last_wg_transfer
        ):
            self.last_wg_transfer = transfer
            self.last_wg_ts = now
            self.wg_rx_rate = 0.0
            self.wg_tx_rate = 0.0
            return wg_if, (cur_rx, cur_tx)

        dt = max(0.5, now - self.last_wg_ts)
        prev_rx, prev_tx = self.last_wg_transfer[wg_if]

        self.wg_rx_rate = (cur_rx - prev_rx) / dt
        self.wg_tx_rate = (cur_tx - prev_tx) / dt

        self.last_wg_transfer = transfer
        self.last_wg_ts = now
        return wg_if, (cur_rx, cur_tx)

    # ---------- DNS apply ----------
    def apply_dns(self, choice=None, refresh_ui=True, update_choice_var=True):
        controls_locked, lock_reason = self._dns_controls_locked()
        if controls_locked:
            if lock_reason == "transition":
                warning_message = self.tr(
                    "dns_warning_locked_transition_message",
                    "Es läuft gerade ein VPN-/DNS-Wechsel.\n\n"
                    "Bitte warten, bis der Vorgang abgeschlossen ist. "
                    "Währenddessen ist ein manueller DNS-Wechsel gesperrt.",
                )
                result = (
                    "=== DNS anwenden ===\n"
                    "Status: blockiert\n"
                    "Grund: VPN-/DNS-Wechsel läuft.\n\n"
                    "Bitte warten, bis der laufende Vorgang abgeschlossen ist."
                )
                log_message = "DNS anwenden blockiert: VPN-/DNS-Wechsel läuft"
            else:
                warning_message = self.tr(
                    "dns_warning_locked_vpn_message",
                    "VPN ist aktiv.\n\n"
                    "DNS wird vom VPN-Profil verwaltet. "
                    "Ein manueller DNS-Wechsel kann DNS-Leaks verursachen.",
                )
                result = (
                    "=== DNS anwenden ===\n"
                    "Status: blockiert\n"
                    "Grund: VPN ist aktiv.\n\n"
                    "DNS wird vom VPN-Profil verwaltet. Ein manueller DNS-Wechsel "
                    "würde DNS-Leaks verursachen."
                )
                log_message = "DNS anwenden blockiert: VPN aktiv"
            messagebox.showwarning(
                self.tr("dns_warning_locked_title", "DNS gesperrt"),
                warning_message,
                parent=self,
            )
            self.nb.select(self.tab_dns)
            self.update_dns_output(result)
            self.log_safe(log_message)
            self.update_dns_controls_state_safe()
            return False
        choice = self._normalize_dns_profile_choice(choice)
        if update_choice_var:
            self._set_dns_choice_safe(choice)

        self.nb.select(self.tab_dns)
        self.log_safe("DNS-Profil wird angewendet...")

        result = self._apply_dns_profile_choice_via_control(choice)
        self.update_dns_output(
            self._format_dns_profile_control_result(
                result,
                heading="=== DNS anwenden ===",
                action="DNS-Profil anwenden",
            )
        )

        if not result["success"]:
            self.log_safe("DNS anwenden fehlgeschlagen")
            self.refresh_dns_policy_status()
            self.update_dns_controls_state_safe()
            return False

        self.log_safe(f"DNS-Profil angewendet: {choice}")
        self.last_dns_consistency_ok = None
        self.last_dns_consistency_ts = 0.0
        self.dns_consistency_enabled = True
        self.dns_consistency_one_shot = True
        self.dns_consistency_check_async(force=True)
        self.refresh_dns_policy_status()
        self.update_dns_controls_state_safe()
        if refresh_ui:
            self.refresh_safe()
        return True

    def show_dns_status(self):
        self.nb.select(self.tab_dns)
        self.log(self.tr("dns_log_status_updated", "DNS-Status aktualisiert"))
        if not has_cmd("nmcli"):
            self.update_dns_output(
                "=== DNS Status (nmcli) ===\n"
                "Ergebnis: fehlgeschlagen\nDetails: nmcli fehlt – NetworkManager ist nicht verfügbar."
            )
            return
        iface = self.get_default_iface()
        _, out = run_cmd(["nmcli", "dev", "show", iface], timeout=8)
        if not out:
            self.update_dns_output(
                "=== DNS Status (nmcli) ===\n"
                f"Interface: {iface}\nErgebnis: keine Ausgabe"
            )
            return
        lines = [ln for ln in out.splitlines() if "IP4.DNS" in ln or "IP4.DOMAIN" in ln]
        body = "\n".join(lines) if lines else out
        self.update_dns_output(
            "=== DNS Status (nmcli) ===\n" f"Interface: {iface}\n\n{body}"
        )

    # ---------- DNS Consistency check ----------
    def enable_dns_consistency_test(self):
        was_enabled = self.dns_consistency_enabled
        self.dns_consistency_enabled = True
        self.dns_consistency_one_shot = False
        self.last_dns_consistency_ok = None
        self.last_dns_consistency_ts = 0.0
        self.nb.select(self.tab_dns)
        self.update_dns_output(
            "=== DNS-Konsistenztest ===\nStatus: gestartet\n"
            f"Zeit: {datetime.now().strftime('%Y-%m-%d %H:%M:%S')}"
        )
        self.log(
            self.tr(
                "dns_log_consistency_started",
                "DNS-Konsistenztest gestartet",
            )
        )
        self.refresh()
        if not was_enabled or not self.dns_consistency_running:
            self.dns_consistency_check_async(force=True)

    def disable_dns_consistency_test(self):
        self.dns_consistency_enabled = False
        self.dns_consistency_one_shot = False
        self.last_dns_consistency_ok = None
        self.last_dns_consistency_ts = 0.0
        self.nb.select(self.tab_dns)
        self.update_dns_output(
            "=== DNS-Konsistenztest ===\nStatus: gestoppt\n"
            f"Zeit: {datetime.now().strftime('%Y-%m-%d %H:%M:%S')}"
        )
        self.log(
            self.tr(
                "dns_log_consistency_stopped",
                "DNS-Konsistenztest gestoppt",
            )
        )
        self.refresh()

    def dns_consistency_check_async(self, force=False):
        if not self.dns_consistency_enabled and not force:
            return
        if self.dns_consistency_running:
            return
        if not force and (time.time() - self.last_dns_consistency_ts) < 30:
            return

        if not (has_cmd("dig") or has_cmd("nslookup")):
            self.nb.select(self.tab_dns)
            self.update_dns_output(
                "=== DNS-Konsistenztest ===\n"
                "Ergebnis: nicht ausführbar\n"
                "Details: weder 'dig' noch 'nslookup' gefunden. Install: sudo apt install dnsutils"
            )
            self.log(
                self.tr(
                    "dns_log_consistency_start_failed",
                    "DNS-Konsistenztest konnte nicht gestartet werden",
                )
            )
            self.last_dns_consistency_ok = None
            self.last_dns_consistency_ts = time.time()
            return

        self.dns_consistency_running = True
        choice = self.dns_choice.get()

        def job():
            try:
                selected = DNS_PROFILES.get(choice)
                test_domain = "example.com"
                killswitch_active = self.killswitch_is_on()
                vpn_active = bool(self.active_wg_profile())

                def sys_query():
                    if has_cmd("dig"):
                        _, out = run_cmd(
                            ["dig", "+time=2", "+tries=1", "+short", "A", test_domain],
                            timeout=5,
                        )
                        return out.strip()
                    _, out = run_cmd(["nslookup", "-timeout=2", test_domain], timeout=5)
                    return out.strip()

                def explicit_query(server: str):
                    if has_cmd("dig"):
                        _, out = run_cmd(
                            [
                                "dig",
                                "+time=2",
                                "+tries=1",
                                "+short",
                                "A",
                                test_domain,
                                f"@{server}",
                            ],
                            timeout=5,
                        )
                        return out.strip()
                    _, out = run_cmd(
                        ["nslookup", "-timeout=2", test_domain, server], timeout=5
                    )
                    return out.strip()

                def http_query():
                    if not has_cmd("curl"):
                        return None
                    rc, _ = run_cmd(
                        ["curl", "-fsS", "--max-time", "4", "https://example.com"],
                        timeout=6,
                    )
                    return rc == 0

                def build_network_context_lines(dns_ok, http_ok):
                    lines = [f"DNS-Auflösung: {'OK' if dns_ok else '—'}"]
                    if http_ok is None:
                        lines.append("HTTP-Test: übersprungen (curl fehlt)")
                    else:
                        lines.append(f"HTTP-Test: {'OK' if http_ok else 'blockiert'}")
                    if killswitch_active and not vpn_active:
                        lines.append(
                            "Hinweis: Killswitch ist AN – ohne VPN evtl. kein Internet (gewollt)."
                        )
                    return lines

                sys_ok = bool(sys_query())
                http_ok = http_query()
                timestamp = datetime.now().strftime("%Y-%m-%d %H:%M:%S")

                if selected is None:
                    self.last_dns_consistency_ok = None
                    self.last_dns_consistency_ts = time.time()
                    detail_text = "\n".join(
                        [
                            "=== DNS-Konsistenztest ===",
                            f"Zeit: {timestamp}",
                            f"Profil: {choice}",
                            "Ergebnis: System(auto)",
                            f"System DNS answer: {'OK' if sys_ok else '—'}",
                            "",
                            *build_network_context_lines(sys_ok, http_ok),
                        ]
                    )

                    def show_auto_result():
                        self.nb.select(self.tab_dns)
                        self.update_dns_output(detail_text, append=True)
                        self.log("DNS-Konsistenztest aktualisiert")

                    self.after(0, show_auto_result)
                    return

                explicit_results = [(s, bool(explicit_query(s))) for s in selected]
                any_explicit_ok = any(ok for _, ok in explicit_results)
                dns_ok = sys_ok or any_explicit_ok

                if (not sys_ok) and (not any_explicit_ok):
                    self.last_dns_consistency_ok = None
                    self.last_dns_consistency_ts = time.time()
                    detail_text = "\n".join(
                        [
                            "=== DNS-Konsistenztest ===",
                            f"Zeit: {timestamp}",
                            f"Profil: {choice}",
                            "Ergebnis: nicht testbar (keine DNS-Antworten)",
                            "",
                            *build_network_context_lines(dns_ok, http_ok),
                        ]
                    )

                    def show_no_dns_result():
                        self.nb.select(self.tab_dns)
                        self.update_dns_output(detail_text, append=True)
                        self.log("DNS-Konsistenztest aktualisiert")

                    self.after(0, show_no_dns_result)
                    return

                ok = sys_ok and any_explicit_ok
                self.last_dns_consistency_ok = ok
                self.last_dns_consistency_ts = time.time()
                explicit_line = ", ".join(
                    [f"{s}->{('OK' if ok2 else '—')}" for s, ok2 in explicit_results]
                )
                detail_text = "\n".join(
                    [
                        "=== DNS-Konsistenztest ===",
                        f"Zeit: {timestamp}",
                        f"Profil: {choice}",
                        f"System DNS answer: {'OK' if sys_ok else '—'}",
                        f"Explizit gewählt: {explicit_line}",
                        "Ergebnis: "
                        + ("OK" if ok else "MÖGLICHE Abweichung (System/Resolver)"),
                        "",
                        *build_network_context_lines(dns_ok, http_ok),
                    ]
                )

                def show_result():
                    self.nb.select(self.tab_dns)
                    self.update_dns_output(detail_text, append=True)
                    self.log("DNS-Konsistenztest aktualisiert")

                self.after(0, show_result)

            finally:
                self.dns_consistency_running = False
                if self.__dict__.get("dns_consistency_one_shot", False):
                    self.dns_consistency_one_shot = False
                    self.dns_consistency_enabled = False
                    self.after(0, lambda: self.log("DNS-Konsistenztest gestoppt"))
                self._update_dns_consistency_light_safe()

        threading.Thread(target=job, daemon=True).start()

    # ---------- Actions ----------
    def fw_enable(self, interactive_guard=True):
        if interactive_guard and not self._confirm_danger_action(
            "firewall:enable",
            title=self.tr("firewall_confirm_enable_title", "Firewall aktivieren"),
            prompt=self.tr(
                "firewall_confirm_enable_prompt",
                "Diese Aktion aktiviert UFW systemweit.\n"
                "Dadurch kann sich das Netzwerkverhalten sofort ändern.\n\n"
                "Wirklich fortfahren?",
            ),
            cooldown_s=0,
            require_phrase="AUSFUEHREN",
        ):
            self.log(
                self.tr(
                    "firewall_log_enable_cancelled",
                    "Firewall-Aktivierung abgebrochen.",
                )
            )
            return

        if not self.ensure_sudo_session("Firewall aktivieren"):
            return

        def job():
            if self.check_ufw_active():
                self.after(
                    0,
                    lambda: self.log(
                        self.tr(
                            "firewall_log_already_enabled",
                            "Firewall ist bereits aktiv.",
                        )
                    ),
                )
                return

            rc, out = run_cmd(["sudo", "-n", "ufw", "--force", "enable"], timeout=40)

            if rc != 0:
                self.after(
                    0,
                    lambda: self.log(
                        self.tr(
                            "firewall_log_enable_failed",
                            "Firewall konnte NICHT aktiviert werden",
                        )
                    ),
                )
                if out:
                    self.after(0, lambda: self.log(out))
            else:
                self.after(
                    0,
                    lambda: self.log(
                        self.tr("firewall_log_enabled", "Firewall aktiviert.")
                    ),
                )

            self.after(0, self.refresh)

        self.run_async(job)

    def _parse_ufw_action(self, action_text):
        text = str(action_text or "").strip()
        if not text:
            return "", ""
        parts = text.upper().split()
        policy = parts[0] if parts else ""
        direction = ""
        for token in parts[1:]:
            if token in {"IN", "OUT"}:
                direction = token
                break
        if not direction:
            lower = text.lower()
            if " out" in lower or lower.endswith("out"):
                direction = "OUT"
            elif " in" in lower or lower.endswith("in"):
                direction = "IN"
        return policy, direction

    def _extract_ip_port_proto_from_ufw_to(self, to_text):
        text = str(to_text or "").strip()
        ip_val = None
        port_val = None
        proto_val = ""

        m = re.search(r"(?P<port>\d{1,5})/(?P<proto>tcp|udp)\b", text, re.IGNORECASE)
        if m:
            port_val = m.group("port")
            proto_val = m.group("proto").lower()
        else:
            m_port = re.search(r"\bport\s+(?P<port>\d{1,5})\b", text, re.IGNORECASE)
            if m_port:
                port_val = m_port.group("port")

        cleaned = (
            text.replace("[", " ").replace("]", " ").replace("(", " ").replace(")", " ")
        )
        for token in re.split(r"[\s,]+", cleaned):
            cand = token.strip()
            if not cand:
                continue
            try:
                ipaddress.ip_address(cand)
                ip_val = cand
                break
            except ValueError:
                continue

        return ip_val, port_val, proto_val

    def _is_ufw_non_rule_line(self, line):
        text = str(line or "").strip()
        if not text:
            return True

        lower = text.lower()
        meta_prefixes = (
            "status:",
            "new profiles:",
            "logging:",
            "protokollierung:",
            "voreinstellung:",
            "default:",
        )
        if lower.startswith(meta_prefixes):
            return True

        header_tokens = {
            "aktion",
            "action",
            "zu",
            "to",
            "von",
            "from",
        }
        compact = re.sub(r"\s+", " ", text).strip().lower()
        if compact in {
            "aktion zu von",
            "action to from",
            "to action from",
            "zu aktion von",
        }:
            return True
        if set(compact.split()) <= header_tokens and len(compact.split()) >= 2:
            return True

        if re.fullmatch(r"[-=]{3,}.*", text):
            return True

        return False

    def _parse_ufw_structured_rule(self, raw_line):
        line = str(raw_line or "").strip()
        if self._is_ufw_non_rule_line(line):
            return None

        line_norm = re.sub(r"\s+", " ", line).strip()
        action_match = re.search(
            r"\b(ALLOW|DENY|REJECT)\b(?:\s+(IN|OUT))?\b",
            line_norm,
            re.IGNORECASE,
        )
        if not action_match:
            return None

        policy = (action_match.group(1) or "").upper()
        direction = (action_match.group(2) or "").upper()

        to_field = line_norm[: action_match.start()].strip()
        from_field = line_norm[action_match.end() :].strip()
        if not to_field:
            return None

        is_ipv6 = "(v6)" in line.lower()
        to_clean = re.sub(r"\s*\(v6\)\s*", "", to_field, flags=re.IGNORECASE).strip()
        from_clean = re.sub(
            r"\s*\(v6\)\s*", "", from_field, flags=re.IGNORECASE
        ).strip()

        interface = None
        target_base = to_clean
        m_iface = re.search(
            r"^(?P<target>.+?)\s+on\s+(?P<iface>[A-Za-z0-9_.:-]+)$",
            to_clean,
            re.IGNORECASE,
        )
        if m_iface:
            target_base = m_iface.group("target").strip()
            interface = m_iface.group("iface").strip()

        ip_val, port_val, proto_val = self._extract_ip_port_proto_from_ufw_to(
            target_base
        )

        category = "other"
        if interface:
            category = "interface"
        elif proto_val.lower() == "udp" and ip_val and port_val:
            category = "vpn_endpoint"
        elif port_val:
            category = "standard_port"

        if category == "interface":
            display = target_base or "Anywhere"
        elif category == "vpn_endpoint":
            display = f"{ip_val}:{port_val}/{proto_val}"
        elif category == "standard_port":
            if ip_val and proto_val:
                display = f"{ip_val}:{port_val}/{proto_val}"
            elif proto_val:
                display = f"{port_val}/{proto_val}"
            else:
                display = f"{port_val}"
        else:
            display = target_base or line_norm

        return {
            "direction": direction,
            "policy": policy,
            "interface": interface,
            "ip": ip_val,
            "port": port_val,
            "proto": proto_val,
            "is_ipv6": bool(is_ipv6),
            "raw": line,
            "to": to_clean,
            "from": from_clean,
            "category": category,
            "target_base": target_base,
            "display": display,
        }

    def _ip_sort_key(self, value):
        text = str(value or "").strip()
        if not text:
            return (2, "")
        try:
            addr = ipaddress.ip_address(text)
            return (0, addr.version, int(addr))
        except ValueError:
            return (1, text)

    def _ufw_rule_sort_key(self, rule):
        category = rule.get("category")
        policy = rule.get("policy") or ""
        direction = rule.get("direction") or ""
        if category == "interface":
            return ((rule.get("interface") or ""), direction, policy)
        if category == "standard_port":
            port = int(rule.get("port") or 0)
            proto = rule.get("proto") or ""
            return (port, proto, direction, policy, rule.get("display") or "")
        if category == "vpn_endpoint":
            return (
                self._ip_sort_key(rule.get("ip")),
                int(rule.get("port") or 0),
                direction,
                policy,
            )
        return (rule.get("display") or rule.get("raw") or "",)

    def _format_ufw_rule_lines(self, rules):
        if not rules:
            return ["(keine Regeln)"]

        dedup = {}
        for rule in rules:
            action = (rule.get("policy") or "-").upper() or "-"
            direction = (rule.get("direction") or "-").upper() or "-"
            target = (
                rule.get("display") or rule.get("to") or rule.get("raw") or "-"
            ).strip() or "-"
            iface = (rule.get("interface") or "-").strip() or "-"
            key = (action, direction, target, iface)
            dedup[key] = dedup.get(key, 0) + 1

        rows = sorted(
            dedup.items(),
            key=lambda item: (item[0][0], item[0][1], item[0][2], item[0][3]),
        )

        action_w = 6
        direction_w = 9
        target_w = 30
        iface_w = 18

        header = f"{'AKTION':<6} {'RICHTUNG':<9} {'ZIEL':<30} {'INTERFACE':<18}"
        sep = "-" * len(header)

        lines = [header, sep]
        for (action, direction, target, iface), count in rows:
            action = (action or "-")[:action_w]
            direction = (direction or "-")[:direction_w]
            iface = (iface or "-")[:iface_w]
            if len(target) > target_w:
                target = target[: target_w - 1] + "…"
            suffix = f" [DUP x{count}]" if count > 1 else ""
            lines.append(f"{action:<6} {direction:<9} {target:<30} {iface:<18}{suffix}")
        return lines

    def _format_ufw_status_grouped(
        self, status_label, default_in, default_out, rules, metadata=None
    ):
        v4_rules = [r for r in rules if not r.get("is_ipv6")]
        v6_rules = [r for r in rules if r.get("is_ipv6")]

        def by_cat(items, cat):
            return [r for r in items if r.get("category") == cat]

        metadata = metadata or []
        sections = [
            "Firewall-Status",
            f"Aktiv: {status_label}",
            f"Default IN: {default_in}",
            f"Default OUT: {default_out}",
        ]
        if metadata:
            sections.append("")
            sections.append("Metadaten")
            for item in metadata:
                sections.append(f"- {item}")

        sections.extend(
            [
                "",
                "=== INTERFACE REGELN (IPv4) ===",
                *self._format_ufw_rule_lines(by_cat(v4_rules, "interface")),
                "",
                "=== STANDARD PORTS (IPv4) ===",
                *self._format_ufw_rule_lines(by_cat(v4_rules, "standard_port")),
                "",
                "=== VPN ENDPOINTS (UDP IPv4) ===",
                *self._format_ufw_rule_lines(by_cat(v4_rules, "vpn_endpoint")),
            ]
        )

        v4_other = by_cat(v4_rules, "other")
        if v4_other:
            sections.extend(
                [
                    "",
                    "=== SONSTIGES (IPv4) ===",
                    *self._format_ufw_rule_lines(v4_other),
                ]
            )

        sections.extend(
            [
                "",
                "=== INTERFACE REGELN (IPv6) ===",
                *self._format_ufw_rule_lines(by_cat(v6_rules, "interface")),
                "",
                "=== STANDARD PORTS (IPv6) ===",
                *self._format_ufw_rule_lines(by_cat(v6_rules, "standard_port")),
                "",
                "=== VPN ENDPOINTS (UDP IPv6) ===",
                *self._format_ufw_rule_lines(by_cat(v6_rules, "vpn_endpoint")),
            ]
        )

        v6_other = by_cat(v6_rules, "other")
        if v6_other:
            sections.extend(
                [
                    "",
                    "=== SONSTIGES (IPv6) ===",
                    *self._format_ufw_rule_lines(v6_other),
                ]
            )

        return "\n".join(sections)

    def fw_status(self):
        if not self.ensure_sudo_session("Firewall Status lesen"):
            return
        with self.ufw_lock:
            rc, out = run_cmd(["sudo", "-n", "ufw", "status", "verbose"], timeout=12)

        if rc != 0:
            self.log(
                self.tr(
                    "firewall_log_status_read_failed",
                    "Firewall-Status konnte nicht gelesen werden.",
                )
            )
            if out:
                self.log(out)
            return

        status_label = "unbekannt"
        default_in = "-"
        default_out = "-"
        metadata_lines = []
        structured_rules = []

        for raw_line in (out or "").splitlines():
            line = raw_line.strip()
            if not line:
                continue

            lower = line.lower()
            if lower.startswith("status:"):
                status_label = line.split(":", 1)[1].strip() or "unbekannt"
                continue

            if lower.startswith("default:") or lower.startswith("voreinstellung:"):
                default_text = line.split(":", 1)[1].strip() if ":" in line else line
                match_in = re.search(
                    r"(allow|deny|reject)\s*\((incoming|eingehend)\)",
                    default_text,
                    re.IGNORECASE,
                )
                match_out = re.search(
                    r"(allow|deny|reject)\s*\((outgoing|abgehend|ausgehend)\)",
                    default_text,
                    re.IGNORECASE,
                )
                if match_in:
                    default_in = match_in.group(1).upper()
                if match_out:
                    default_out = match_out.group(1).upper()
                metadata_lines.append(line)
                continue

            if (
                lower.startswith("logging:")
                or lower.startswith("protokollierung:")
                or lower.startswith("new profiles:")
            ):
                metadata_lines.append(line)
                continue

            if self._is_ufw_non_rule_line(line):
                continue

            parsed = self._parse_ufw_structured_rule(line)
            if parsed is not None:
                structured_rules.append(parsed)

        summary = self._format_ufw_status_grouped(
            status_label=status_label,
            default_in=default_in,
            default_out=default_out,
            rules=structured_rules,
            metadata=metadata_lines,
        )
        self.log(summary)

    def fw_disable(self, interactive_guard=True):
        if interactive_guard and not self._confirm_danger_action(
            "firewall:disable",
            title=self.tr("firewall_confirm_disable_title", "Firewall deaktivieren"),
            prompt=self.tr(
                "firewall_confirm_disable_prompt",
                "Diese Aktion deaktiviert UFW systemweit.\n"
                "Dein System kann dadurch unmittelbar weniger geschützt sein.\n\n"
                "Wirklich fortfahren?",
            ),
            cooldown_s=0,
            require_phrase="AUSFUEHREN",
        ):
            self.log(
                self.tr(
                    "firewall_log_disable_cancelled",
                    "Firewall-Deaktivierung abgebrochen.",
                )
            )
            return

        if not self.ensure_sudo_session("Firewall deaktivieren"):
            return

        def job():
            if not self.check_ufw_active():
                self.after(
                    0,
                    lambda: self.log(
                        self.tr(
                            "firewall_log_already_disabled",
                            "Firewall ist bereits deaktiviert.",
                        )
                    ),
                )
                return

            rc, out = run_cmd(["sudo", "-n", "ufw", "disable"], timeout=40)

            if rc != 0:
                self.after(
                    0,
                    lambda: self.log(
                        self.tr(
                            "firewall_log_disable_failed",
                            "Firewall konnte NICHT deaktiviert werden",
                        )
                    ),
                )
                if out:
                    self.after(0, lambda: self.log(out))
            else:
                self.after(
                    0,
                    lambda: self.log(
                        self.tr("firewall_log_disabled", "Firewall deaktiviert.")
                    ),
                )

            self.after(0, self.refresh)

        self.run_async(job)

    def vpn_switch(
        self, target, ensure_sudo=True, refresh_ui=True, force_reconnect=False
    ):
        if not self._try_begin_network_operation(f"VPN wechseln auf {target}"):
            if refresh_ui:
                self.refresh_safe()
            return False
        try:
            target = self._base_wg_profile_name(target)
            self.log_debug(f"Basisprofil = {target!r}")
            if not target:
                self.log_safe(
                    self.tr(
                        "vpn_log_no_profile_selected", "Kein WireGuard-Profil gewählt."
                    )
                )
                self._recover_firewall_after_killswitch_failure()
                if refresh_ui:
                    self.refresh_safe()
                return False

            if ensure_sudo and not self.ensure_sudo_session(
                f"VPN umschalten auf {target}"
            ):
                return False

            self.sync_internal_ipv4_profiles(log_failures=False)
            resolved = self.resolve_profile_family_runtime(target, log_missing=True)
            runtime_target = (resolved.get("runtime_profile") or "").strip()
            preferred_runtime = (
                self.resolve_runtime_vpn_profile(target, log_missing=not runtime_target)
                or ""
            ).strip()
            if preferred_runtime:
                runtime_target = preferred_runtime
            self.log_debug(f"Runtimeprofil = {runtime_target!r}")
            self.log_debug(f"IPv6 deaktiviert = {resolved.get('system_ipv6_disabled')}")
            self.log_debug(
                f"[DEBUG] Resolver {target} -> IPv4={resolved.get('effective_ipv4_interface') or '-'}, "
                f"IPv6={resolved.get('effective_ipv6_interface') or 'None'}, supports_ipv6={resolved.get('supports_ipv6')}"
            )

            if not runtime_target:
                runtime_target = self.resolve_runtime_vpn_profile(
                    target, log_missing=True
                )
            if not runtime_target:
                self._recover_firewall_after_killswitch_failure()
                if refresh_ui:
                    self.refresh_safe()
                return False

            active_iface = (self.get_wg_iface() or "").strip()
            reconnecting_same_profile = active_iface == runtime_target
            if reconnecting_same_profile:
                if not force_reconnect:
                    self.log_safe(
                        self.tr(
                            "vpn_log_profile_already_active",
                            "VPN-Profil bereits aktiv.",
                        )
                    )
                    if refresh_ui:
                        self.refresh_safe()
                    return True
                self.log_safe(
                    self.tr(
                        "vpn_log_force_reconnect",
                        "Vorhandenes Runtimeprofil erkannt - Reconnect wird erzwungen.",
                    )
                )

            if len(runtime_target) > 15:
                self.log_safe(
                    self.tr(
                        "vpn_log_runtime_name_too_long",
                        "VPN Start abgebrochen: Runtime-Profilname '{name}' ist zu lang fuer ein WireGuard-Interface (max 15 Zeichen).",
                    ).format(name=runtime_target)
                )
                self.log_safe(
                    self.tr(
                        "vpn_log_shorten_runtime_name",
                        "Bitte interne IPv4-Runtime-Namen kuerzer bilden.",
                    )
                )
                if refresh_ui:
                    self.refresh_safe()
                return False

            network_service = self._network_service()
            runtime_path = self._wg_profile_path(runtime_target)
            self._check_wireguard_profile_for_multiple_endpoints(
                runtime_target, runtime_path
            )
            if network_service is not None:
                rc_check, out_check = network_service.file_exists(runtime_path)
            else:
                rc_check, out_check = run_cmd(
                    ["sudo", "-n", "test", "-f", runtime_path], timeout=5
                )
            self.log_debug_safe(f"Runtimepfad = {runtime_path}")
            self.log_debug_safe(f"sudo test -f Runtimepfad rc = {rc_check}")
            if rc_check != 0:
                self.log_safe(
                    self.tr(
                        "vpn_log_runtime_file_missing",
                        "VPN Start abgebrochen: Runtime-Datei nicht gefunden: {path}",
                    ).format(path=runtime_path)
                )
                if out_check:
                    self.log_safe(out_check)
                if refresh_ui:
                    self.refresh_safe()
                return False

            self.prepare_dns_for_vpn_profile_switch()

            for iface in self.get_wg_interfaces():
                if iface != runtime_target or reconnecting_same_profile:
                    if network_service is not None:
                        network_service.wg_quick_down(iface, timeout=12)
                    else:
                        run_cmd(["sudo", "-n", "wg-quick", "down", iface], timeout=12)

            if self.ipv6_is_disabled() and runtime_target == target:
                self.log_safe(
                    "IPv6 ist global deaktiviert - aktiviere IPv6 vor VPN-Start."
                )
                self.ipv6_enable(refresh_ui=False)

            if network_service is not None:
                rc, out = network_service.wg_quick_up(runtime_target, timeout=20)
            else:
                rc, out = run_cmd(
                    ["sudo", "-n", "wg-quick", "up", runtime_target], timeout=20
                )
            if rc == 0:
                if force_reconnect:
                    self.log_safe(
                        self.tr(
                            "vpn_log_reconnected",
                            "VPN Verbindung neu aufgebaut.",
                        )
                    )
                else:
                    self.log_safe(
                        self.tr("vpn_log_connected", "VPN Verbindung aufgebaut.")
                    )
                self.log_safe(
                    self.tr("vpn_log_started", "VPN gestartet: {target}").format(
                        target=target
                    )
                )
                self.log_debug_safe(out)
            else:
                self.log_safe(
                    self.tr(
                        "vpn_log_start_failed_rc", "VPN Start fehlgeschlagen: rc={rc}"
                    ).format(rc=rc)
                )
                if out:
                    self.log_safe((out or "").strip())
                self.log_debug_safe(out)

            self.last_wg_transfer = None
            self.last_wg_ts = None
            self.refresh_wg_profiles()
            self.update_primary_vpn_form_controls()
            self.sync_primary_vpn_form_selection()
            if rc == 0 and self.killswitch_is_on():
                self._killswitch_on_sync(refresh_ui=False)
            if rc == 0:
                self._schedule_dns_finalize_after_vpn_profile_switch(delay_ms=2500)
                self.run_async(lambda t=target: self.verify_vpn_exit_country(t))
            else:
                self._schedule_dns_finalize_after_vpn_profile_switch(delay_ms=750)

            self.update_ipv6_controls_state_safe()
            if refresh_ui:
                self.refresh_safe()
            return rc == 0
        finally:
            self._end_network_operation()

    def vpn_off(self, ensure_sudo=True, refresh_ui=True):
        if not self._try_begin_network_operation("VPN deaktivieren"):
            if refresh_ui:
                self.refresh_safe()
            return False
        try:
            if ensure_sudo and not self.ensure_sudo_session("VPN deaktivieren"):
                return False
            network_service = self._network_service()
            targets = sorted(
                set(self.wg_profiles + self.get_wg_interfaces() + [VPN_CH, VPN_DE])
            )
            for target in targets:
                if network_service is not None:
                    network_service.wg_quick_down(target, timeout=12)
                else:
                    run_cmd(["sudo", "-n", "wg-quick", "down", target], timeout=12)
            self.log_safe(self.tr("vpn_log_disabled", "VPN deaktiviert."))
            self.prepare_dns_for_vpn_profile_switch()
            self._schedule_dns_finalize_after_vpn_profile_switch(delay_ms=2500)
            if self.killswitch_is_on():
                self.log_safe(
                    self.tr(
                        "killswitch_log_notice_enabled_without_vpn",
                        "HINWEIS: Killswitch ist AN – ohne VPN evtl. kein Internet (gewollt).",
                    )
                )
            self.refresh_wg_profiles()
            self.update_ipv6_controls_state_safe()
            if refresh_ui:
                self.refresh_safe()
            return True
        finally:
            self._end_network_operation()

    def _recover_firewall_after_killswitch_failure(self):
        network_service = self._network_service()
        cmds = [
            ["sudo", "-n", "ufw", "default", "allow", "outgoing"],
            ["sudo", "-n", "ufw", "default", "deny", "incoming"],
            ["sudo", "-n", "ufw", "allow", "out", "53/udp"],
            ["sudo", "-n", "ufw", "allow", "out", "53/tcp"],
            ["sudo", "-n", "ufw", "allow", "out", "443/tcp"],
            ["sudo", "-n", "ufw", "allow", "out", "80/tcp"],
        ]
        with self.ufw_lock:
            for cmd in cmds:
                if network_service is not None:
                    network_service.run(cmd, timeout=20)
                else:
                    run_cmd(cmd, timeout=20)

    def _killswitch_on_sync(self, refresh_ui=True):
        if not self._try_begin_network_operation("Killswitch aktivieren"):
            if refresh_ui:
                self.refresh_safe()
            return False
        try:
            referenced_profiles = self._collect_referenced_vpn_profiles(
                include_active=True
            )
            wg_ifaces = sorted(
                set(self._collect_interface_rules_for_profiles(referenced_profiles))
            )
            wg_ifaces = sorted(set(wg_ifaces) | set(self.get_wg_interfaces()))
            handshake_rules = sorted(set(self.get_killswitch_vpn_endpoints()))
            for profile in self._collect_referenced_vpn_profiles(include_active=True):
                resolved = self.resolve_profile_family_runtime(
                    profile, log_missing=False
                )
                self.log_debug(
                    f"[DEBUG] UFW-Regeln für {profile} basieren auf "
                    f"IPv4={resolved.get('effective_ipv4_interface') or '-'}, "
                    f"IPv6={resolved.get('effective_ipv6_interface') or 'None'}"
                )
            if not wg_ifaces and not handshake_rules:
                self.log_safe(
                    self.tr(
                        "killswitch_log_no_profile_with_endpoint",
                        "Kein WireGuard-Profil mit Endpoint gefunden – Killswitch kann nicht aktiviert werden.",
                    )
                )
                return False

            network_service = self._network_service()
            with self.ufw_lock:
                rc_s, out_s = self._read_ufw_status()
                ufw_on = (rc_s == 0) and self._ufw_status_is_active(out_s)
                if not ufw_on:
                    if network_service is not None:
                        rc_enable, out_enable = network_service.ufw_enable_force(
                            timeout=20
                        )
                    else:
                        rc_enable, out_enable = run_cmd(
                            ["sudo", "-n", "ufw", "--force", "enable"], timeout=20
                        )
                    if rc_enable != 0:
                        self.log_safe(
                            self.tr(
                                "killswitch_log_enable_failed_ufw",
                                "Killswitch-Aktivierung fehlgeschlagen: UFW konnte nicht aktiviert werden.",
                            )
                        )
                        if out_enable:
                            self.log_safe(out_enable)
                        return False

                cmds = [
                    ["sudo", "-n", "ufw", "default", "deny", "outgoing"],
                    ["sudo", "-n", "ufw", "default", "deny", "incoming"],
                    ["sudo", "-n", "ufw", "allow", "in", "on", "lo"],
                    ["sudo", "-n", "ufw", "allow", "out", "on", "lo"],
                    ["sudo", "-n", "ufw", "allow", "out", "53/udp"],
                    ["sudo", "-n", "ufw", "allow", "out", "53/tcp"],
                    ["sudo", "-n", "ufw", "allow", "out", "443/tcp"],
                    ["sudo", "-n", "ufw", "allow", "out", "80/tcp"],
                ]
                for wg_if in wg_ifaces:
                    cmds.extend(
                        [
                            ["sudo", "-n", "ufw", "allow", "out", "on", wg_if],
                            ["sudo", "-n", "ufw", "allow", "in", "on", wg_if],
                        ]
                    )
                for endpoint_ip, endpoint_port in handshake_rules:
                    cmds.append(
                        [
                            "sudo",
                            "-n",
                            "ufw",
                            "allow",
                            "out",
                            "to",
                            endpoint_ip,
                            "port",
                            endpoint_port,
                            "proto",
                            "udp",
                        ]
                    )

                command_failures = []
                for cmd in cmds:
                    if network_service is not None:
                        rc_cmd, out_cmd = network_service.run(cmd, timeout=20)
                    else:
                        rc_cmd, out_cmd = run_cmd(cmd, timeout=20)
                    if rc_cmd != 0:
                        command_failures.append((cmd, out_cmd))

                rc_v, out_v = self._read_ufw_status(verbose=True)

            if command_failures:
                failed_cmd = " ".join(command_failures[0][0][3:])
                self.log_safe(
                    self.tr(
                        "killswitch_log_enable_failed_command",
                        "Killswitch-Aktivierung fehlgeschlagen: UFW-Befehl fehlgeschlagen ({command}).",
                    ).format(command=failed_cmd)
                )
                failure_out = command_failures[0][1]
                if failure_out:
                    self.log_safe(failure_out)
                self._recover_firewall_after_killswitch_failure()
                if refresh_ui:
                    self.refresh_safe()
                return False

            if rc_v != 0:
                self.log_safe(
                    self.tr(
                        "killswitch_log_enable_failed_verify",
                        "Killswitch-Aktivierung fehlgeschlagen: UFW-Status konnte nicht verifiziert werden.",
                    )
                )
                if out_v:
                    self.log_safe(out_v)
                self._recover_firewall_after_killswitch_failure()
                if refresh_ui:
                    self.refresh_safe()
                return False

            verified, issues = self._verify_killswitch_rules(
                out_v,
                enabled=True,
                wg_ifaces=wg_ifaces,
                handshake_rules=handshake_rules,
            )
            if not verified:
                self.log_safe(
                    self.tr(
                        "killswitch_log_enable_incomplete",
                        "Killswitch-Aktivierung unvollstaendig: UFW-Regeln entsprechen nicht dem erwarteten Endzustand.",
                    )
                )
                self.log_safe(
                    self.tr("label_details_prefix", "Details: ") + "; ".join(issues[:3])
                )
                self._recover_firewall_after_killswitch_failure()
                if refresh_ui:
                    self.refresh_safe()
                return False

            for endpoint_ip, endpoint_port in handshake_rules:
                self.log_safe(
                    self.tr(
                        "killswitch_log_handshake_allowed",
                        "Killswitch: WireGuard Handshake erlaubt für {endpoint}",
                    ).format(endpoint=f"{endpoint_ip}:{endpoint_port}")
                )
            if wg_ifaces:
                allowed_ifaces = ", ".join(wg_ifaces)
                self.log_safe(
                    self.tr(
                        "killswitch_log_enabled_ifaces",
                        "Killswitch AN – nur Traffic über {ifaces}, Loopback und WireGuard-Handshake erlaubt.",
                    ).format(ifaces=allowed_ifaces)
                )
            else:
                self.log_safe(
                    self.tr(
                        "killswitch_log_enabled_basic",
                        "Killswitch AN – Loopback und WireGuard-Handshake erlaubt, Tunnelaufbau kann starten.",
                    )
                )
            if refresh_ui:
                self.refresh_safe()
            return True
        finally:
            self._end_network_operation()

    def killswitch_on(
        self,
        async_mode=True,
        ensure_sudo=True,
        refresh_ui=True,
        interactive_guard=True,
    ):
        if (
            interactive_guard
            and ensure_sudo
            and not self._confirm_danger_action(
                "killswitch:on",
                title=self.tr(
                    "killswitch_confirm_enable_title", "Killswitch aktivieren"
                ),
                prompt=self.tr(
                    "killswitch_confirm_enable_prompt",
                    "Diese Aktion setzt UFW auf restriktive Regeln.\n"
                    "Ohne aktiven VPN-Tunnel kann Internetzugang blockiert werden.\n\n"
                    "Wirklich fortfahren?",
                ),
                cooldown_s=0,
                require_phrase="AUSFUEHREN",
            )
        ):
            self.log(
                self.tr(
                    "killswitch_log_enable_cancelled",
                    "Killswitch-Aktivierung abgebrochen.",
                )
            )
            return False

        if ensure_sudo and not self.ensure_sudo_session("Killswitch aktivieren"):
            return False
        if not async_mode:
            return self._killswitch_on_sync(refresh_ui=refresh_ui)

        def job():
            self._killswitch_on_sync(refresh_ui=refresh_ui)

        self.run_async(job)
        return True

    def _killswitch_off_sync(self, refresh_ui=True):
        if not self._try_begin_network_operation("Killswitch deaktivieren"):
            if refresh_ui:
                self.refresh_safe()
            return False
        try:
            network_service = self._network_service()
            with self.ufw_lock:
                rc_s, out_s = self._read_ufw_status()
                ufw_on = (rc_s == 0) and self._ufw_status_is_active(out_s)
                if not ufw_on:
                    if network_service is not None:
                        rc_enable, out_enable = network_service.ufw_enable_force(
                            timeout=20
                        )
                    else:
                        rc_enable, out_enable = run_cmd(
                            ["sudo", "-n", "ufw", "--force", "enable"], timeout=20
                        )
                    if rc_enable != 0:
                        self.log_safe(
                            self.tr(
                                "killswitch_log_disable_failed_ufw",
                                "Killswitch-Deaktivierung fehlgeschlagen: UFW konnte nicht aktiviert werden.",
                            )
                        )
                        if out_enable:
                            self.log_safe(out_enable)
                        return False

                referenced_profiles = self._collect_referenced_vpn_profiles(
                    include_active=True
                )
                configured_real_ifaces = set(
                    self._collect_interface_rules_for_profiles(referenced_profiles)
                )
                active_ifaces = {
                    str(iface).strip()
                    for iface in self.get_wg_interfaces()
                    if str(iface).strip()
                }
                wg_ifaces = sorted(configured_real_ifaces | active_ifaces)
                wg_ifaces = sorted({w for w in wg_ifaces if w})
                handshake_rules = sorted(set(self.get_killswitch_vpn_endpoints()))

                cleanup_cmds = [
                    ["sudo", "-n", "ufw", "delete", "allow", "in", "on", "lo"],
                    ["sudo", "-n", "ufw", "delete", "allow", "out", "on", "lo"],
                ]
                for wg_if in wg_ifaces:
                    cleanup_cmds.extend(
                        [
                            [
                                "sudo",
                                "-n",
                                "ufw",
                                "delete",
                                "allow",
                                "out",
                                "on",
                                wg_if,
                            ],
                            ["sudo", "-n", "ufw", "delete", "allow", "in", "on", wg_if],
                        ]
                    )
                for endpoint_ip, endpoint_port in handshake_rules:
                    cleanup_cmds.append(
                        [
                            "sudo",
                            "-n",
                            "ufw",
                            "delete",
                            "allow",
                            "out",
                            "to",
                            endpoint_ip,
                            "port",
                            endpoint_port,
                            "proto",
                            "udp",
                        ]
                    )

                for cmd in cleanup_cmds:
                    if network_service is not None:
                        network_service.run(cmd, timeout=20)
                    else:
                        run_cmd(cmd, timeout=20)

                default_cmds = [
                    ["sudo", "-n", "ufw", "default", "allow", "outgoing"],
                    ["sudo", "-n", "ufw", "default", "deny", "incoming"],
                ]
                command_failures = []
                for cmd in default_cmds:
                    if network_service is not None:
                        rc_cmd, out_cmd = network_service.run(cmd, timeout=20)
                    else:
                        rc_cmd, out_cmd = run_cmd(cmd, timeout=20)
                    if rc_cmd != 0:
                        command_failures.append((cmd, out_cmd))

                rc_v, out_v = self._read_ufw_status(verbose=True)

            if command_failures:
                failed_cmd = " ".join(command_failures[0][0][3:])
                self.log_safe(
                    self.tr(
                        "killswitch_log_disable_failed_command",
                        "Killswitch-Deaktivierung fehlgeschlagen: UFW-Befehl fehlgeschlagen ({command}).",
                    ).format(command=failed_cmd)
                )
                failure_out = command_failures[0][1]
                if failure_out:
                    self.log_safe(failure_out)
                if refresh_ui:
                    self.refresh_safe()
                return False

            if rc_v != 0:
                self.log_safe(
                    self.tr(
                        "killswitch_log_disable_failed_verify",
                        "Killswitch-Deaktivierung fehlgeschlagen: UFW-Status konnte nicht verifiziert werden.",
                    )
                )
                if out_v:
                    self.log_safe(out_v)
                if refresh_ui:
                    self.refresh_safe()
                return False

            verified, issues = self._verify_killswitch_rules(
                out_v,
                enabled=False,
                wg_ifaces=wg_ifaces,
                handshake_rules=handshake_rules,
            )
            if not verified:
                self.log_safe(
                    self.tr(
                        "killswitch_log_disable_incomplete",
                        "Killswitch-Deaktivierung unvollstaendig: UFW-Regeln entsprechen nicht dem erwarteten Endzustand.",
                    )
                )
                self.log_safe(
                    self.tr("label_details_prefix", "Details: ") + "; ".join(issues[:3])
                )
                if refresh_ui:
                    self.refresh_safe()
                return False

            self.log_safe(
                self.tr(
                    "killswitch_log_disabled",
                    "Killswitch AUS – UFW bleibt aktiv, normales Routing wieder erlaubt.",
                )
            )
            if refresh_ui:
                self.refresh_safe()
            return True
        finally:
            self._end_network_operation()

    def killswitch_off(
        self,
        async_mode=True,
        ensure_sudo=True,
        refresh_ui=True,
        interactive_guard=True,
    ):
        if (
            interactive_guard
            and ensure_sudo
            and not self._confirm_danger_action(
                "killswitch:off",
                title=self.tr(
                    "killswitch_confirm_disable_title", "Killswitch deaktivieren"
                ),
                prompt=self.tr(
                    "killswitch_confirm_disable_prompt",
                    "Diese Aktion hebt restriktive Killswitch-Regeln auf.\n"
                    "Danach ist normales Routing wieder erlaubt.\n\n"
                    "Wirklich fortfahren?",
                ),
                cooldown_s=0,
                require_phrase="AUSFUEHREN",
            )
        ):
            self.log(
                self.tr(
                    "killswitch_log_disable_cancelled",
                    "Killswitch-Deaktivierung abgebrochen.",
                )
            )
            return False

        if ensure_sudo and not self.ensure_sudo_session("Killswitch deaktivieren"):
            return False
        if not async_mode:
            return self._killswitch_off_sync(refresh_ui=refresh_ui)

        def job():
            self._killswitch_off_sync(refresh_ui=refresh_ui)

        self.run_async(job)
        return True

    def allow_ssh_rule_async(self):
        if not self.ensure_sudo_session("SSH UFW-Regel setzen"):
            return

        def job():
            with self.ufw_lock:
                _, status_out = run_cmd(
                    ["sudo", "-n", "ufw", "status", "numbered"], timeout=12
                )
            if status_out.strip():
                for line in status_out.splitlines():
                    if re.search(
                        r"(^|[^0-9])22/tcp([^0-9]|$)", line, re.IGNORECASE
                    ) or re.search(r"(^|[^0-9])22([^0-9]|$)", line):
                        self.after(
                            0,
                            lambda: self.log(
                                self.tr(
                                    "ssh_log_port_22_already_allowed",
                                    "SSH/UFW: Port 22 ist bereits freigegeben.",
                                )
                            ),
                        )
                        self.after(0, self.refresh)
                        return

            with self.ufw_lock:
                rc, out = run_cmd(["sudo", "-n", "ufw", "allow", "22/tcp"], timeout=15)
            if rc == 0:
                msg = (out or "").strip() or self.tr("ssh_rule_set", "Regel gesetzt.")
                self.after(
                    0,
                    lambda m=msg: self.log(
                        self.tr(
                            "ssh_log_rule_set", "SSH/UFW gesetzt: {message}"
                        ).format(message=m)
                    ),
                )
            else:
                msg = (out or "").strip() or self.tr(
                    "label_unknown_error", "unbekannter Fehler"
                )
                self.after(
                    0,
                    lambda m=msg: self.log(
                        self.tr(
                            "ssh_log_rule_set_failed",
                            "SSH/UFW setzen fehlgeschlagen: {message}",
                        ).format(message=m)
                    ),
                )

            self.after(0, self.refresh)

        threading.Thread(target=job, daemon=True).start()

    def remove_ssh_rule_async(self, auto=False):
        if not self.ensure_sudo_session("SSH UFW-Regeln entfernen"):
            return
        if not auto:
            ok = messagebox.askyesno(
                self.tr("ssh_remove_confirm_title", "Achtung"),
                self.tr(
                    "ssh_remove_confirm_body",
                    "Das entfernt UFW-Regeln für SSH (Port 22).\n"
                    "Wenn du per SSH verbunden bist, kannst du dich aussperren.\n\n"
                    "Wirklich fortfahren?",
                ),
            )
            if not ok:
                self.log(self.tr("ssh_log_cancelled", "SSH/UFW: Abgebrochen."))
                return

        def job():
            with self.ufw_lock:
                _, out = run_cmd(
                    ["sudo", "-n", "ufw", "status", "numbered"], timeout=12
                )
            if not out.strip():
                self.after(
                    0,
                    lambda: self.log(
                        self.tr(
                            "ssh_log_status_numbered_unavailable",
                            "UFW status numbered leer/unverfügbar.",
                        )
                    ),
                )
                return

            matches = []
            for line in out.splitlines():
                m = re.match(r"^\[\s*(\d+)\]\s+(.*)$", line.strip())
                if not m:
                    continue
                num = int(m.group(1))
                rest = m.group(2)
                if re.search(r"(^|[^0-9])22([^0-9]|$)", rest):
                    matches.append((num, rest))

            if not matches:
                self.after(
                    0,
                    lambda: self.log(
                        self.tr(
                            "ssh_log_no_port_22_rule",
                            "SSH/UFW: keine Port-22-Regel gefunden.",
                        )
                    ),
                )
                return

            matches.sort(key=lambda x: x[0], reverse=True)
            for num, rest in matches:
                with self.ufw_lock:
                    rc2, del_out = run_cmd(
                        ["sudo", "-n", "ufw", "--force", "delete", str(num)], timeout=12
                    )
                if rc2 == 0:
                    self.after(
                        0,
                        lambda r=rest: self.log(
                            self.tr(
                                "ssh_log_removed",
                                "SSH/UFW entfernt: {rule}",
                            ).format(rule=r)
                        ),
                    )
                else:
                    self.after(
                        0,
                        lambda o=del_out: self.log(
                            self.tr(
                                "ssh_log_delete_failed",
                                "SSH/UFW delete failed: {message}",
                            ).format(message=o)
                        ),
                    )

            self.after(0, self.refresh)

        threading.Thread(target=job, daemon=True).start()

    def _current_port_reality_target(self):
        candidates = []
        for attr in ("nmap_target", "trace_target", "mtr_target"):
            var = self.__dict__.get(attr)
            if var is None:
                continue
            try:
                value = (var.get() or "").strip()
            except Exception:
                value = ""
            if value:
                candidates.append(value)

        for candidate in candidates:
            if is_safe_trace_target(candidate):
                return candidate
        return "1.1.1.1"

    def _append_port_check_debug_log(self, payload):
        try:
            log_dir = os.path.join(self.netmon_state_dir, "logs")
            os.makedirs(log_dir, exist_ok=True)
            log_path = os.path.join(log_dir, "port_check_debug.log")
            record = dict(payload or {})
            record["ts"] = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
            with open(log_path, "a", encoding="utf-8") as fh:
                fh.write(json.dumps(record, ensure_ascii=False) + "\n")
        except Exception as exc:
            self.log_debug_safe(
                f"Port-Reality-Debuglog konnte nicht geschrieben werden: {exc}"
            )

    def _log_port_reality_result(self, result):
        payload = {
            "event": "port_check",
            "host": result.get("host", "-"),
            "port": int(result.get("port", 0) or 0),
            "state": result.get("state", "unknown"),
            "reason": result.get("reason", ""),
        }
        self._append_port_check_debug_log(payload)

        state = payload["state"]
        host = payload["host"]
        port = payload["port"]
        shown = PORT_REALITY_DISPLAY_MAP.get(state, state)
        self.log_safe(f"Port {port} on {host} → {shown}")

        if state == "pseudo-open":
            self.log_safe(
                "[!] Suspicious port behavior detected (possible NAT/proxy interference)"
            )

    def _store_port_reality_scan(self, host, results):
        self.port_reality_last_scan = {
            "host": host,
            "results": list(results or []),
            "ts": time.time(),
        }

    def _run_port_reality_checks(self, host, ports, source_label="manual"):
        checked_ports = []
        for port in ports:
            try:
                checked_ports.append(int(port))
            except (TypeError, ValueError):
                continue

        if not checked_ports:
            self.log_safe("Port Reality Check: keine gueltigen Ports uebergeben.")
            return []

        self.log_safe(
            f"Port Reality Check gestartet ({source_label}): {host} | Ports: {', '.join(str(p) for p in checked_ports)}"
        )
        results = [
            check_port_real_service(host, port, timeout=3) for port in checked_ports
        ]
        self._store_port_reality_scan(host, results)

        pseudo_count = 0
        for item in results:
            if item.get("state") == "pseudo-open":
                pseudo_count += 1
            self._log_port_reality_result(item)

        if pseudo_count:
            penalty = 5 * pseudo_count
            self.log_safe(
                f"Stability-Hinweis: {pseudo_count} pseudo-open Port(s) erkannt (empfohlener Score-Abzug: -{penalty})."
            )

        return results

    def _run_port_reality_checks_async(self, host, ports, source_label="manual"):
        def job():
            self._run_port_reality_checks(host, ports, source_label=source_label)

        threading.Thread(target=job, daemon=True).start()

    def port_reality_check_async(self):
        host = self._current_port_reality_target()
        if not is_safe_trace_target(host):
            self.log("Port Reality Check: Ziel ungültig/unsicher.")
            return

        ports = tuple(self.port_reality_default_ports)
        self._run_port_reality_checks_async(host, ports, source_label="manual")

    def show_last_port_reality_scan(self):
        scan = dict(self.port_reality_last_scan or {})
        results = list(scan.get("results") or [])
        host = (scan.get("host") or "-").strip() or "-"
        ts = float(scan.get("ts") or 0.0)
        if not results:
            self.log("Port Reality Check: noch kein Scan vorhanden.")
            return

        stamp = datetime.fromtimestamp(ts).strftime("%Y-%m-%d %H:%M:%S") if ts else "-"
        self.log(f"Letzter Port Reality Check ({stamp}) für {host}:")
        for item in results:
            try:
                port = int(item.get("port", 0) or 0)
            except (TypeError, ValueError):
                port = 0
            state = (item.get("state") or "unknown").strip() or "unknown"
            shown = PORT_REALITY_DISPLAY_MAP.get(state, state)
            self.log(f"Port {port} → {shown}")

    def _speedtest_logs_dir(self):
        log_dir = os.path.join(self.netmon_state_dir, "logs")
        os.makedirs(log_dir, exist_ok=True)
        return log_dir

    def _speedtest_history_path(self):
        return os.path.join(self._speedtest_logs_dir(), "speedtest_history.jsonl")

    def _load_speedtest_history(self):
        path = self._speedtest_history_path()
        if not os.path.isfile(path):
            return
        loaded = []
        try:
            with open(path, "r", encoding="utf-8") as fh:
                for line in fh:
                    line = (line or "").strip()
                    if not line:
                        continue
                    try:
                        item = json.loads(line)
                    except Exception:
                        continue
                    if isinstance(item, dict):
                        loaded.append(item)
        except Exception as exc:
            self.log_debug_safe(f"Speedtest-Verlauf konnte nicht geladen werden: {exc}")
            return

        if loaded:
            self.speedtest_history = loaded[-self.speedtest_history_limit :]
            self.speedtest_last_result = dict(self.speedtest_history[-1])
            if len(loaded) > self.speedtest_history_limit:
                self._persist_speedtest_history()

    def _persist_speedtest_history(self):
        path = self._speedtest_history_path()
        records = list(self.speedtest_history[-self.speedtest_history_limit :])
        try:
            os.makedirs(os.path.dirname(path), exist_ok=True)
            with open(path, "w", encoding="utf-8") as fh:
                for item in records:
                    fh.write(json.dumps(item, ensure_ascii=False) + "\n")
        except Exception as exc:
            self.log_debug_safe(
                f"Speedtest-Verlauf konnte nicht gespeichert werden: {exc}"
            )

    def _append_speedtest_history(self, result):
        if not isinstance(result, dict):
            return
        self.speedtest_last_result = dict(result)
        self.speedtest_history.append(dict(result))
        self.speedtest_history = self.speedtest_history[-self.speedtest_history_limit :]
        self._persist_speedtest_history()

    def _speedtest_warn_messages(self, result):
        warns = []
        if not isinstance(result, dict):
            return warns
        dl = result.get("download_mbps")
        ul = result.get("upload_mbps")
        ping = result.get("ping_ms")
        jitter = result.get("jitter_ms")

        if (
            isinstance(dl, (int, float))
            and dl < SPEEDTEST_WARN_DEFAULTS["download_mbps_min"]
        ):
            warns.append(
                f"Download niedrig: {dl:.1f} Mbit/s (< {SPEEDTEST_WARN_DEFAULTS['download_mbps_min']:.1f})"
            )
        if (
            isinstance(ul, (int, float))
            and ul < SPEEDTEST_WARN_DEFAULTS["upload_mbps_min"]
        ):
            warns.append(
                f"Upload niedrig: {ul:.1f} Mbit/s (< {SPEEDTEST_WARN_DEFAULTS['upload_mbps_min']:.1f})"
            )
        if (
            isinstance(ping, (int, float))
            and ping > SPEEDTEST_WARN_DEFAULTS["ping_ms_max"]
        ):
            warns.append(
                f"Ping hoch: {ping:.0f} ms (> {SPEEDTEST_WARN_DEFAULTS['ping_ms_max']:.0f})"
            )
        if (
            isinstance(jitter, (int, float))
            and jitter > SPEEDTEST_WARN_DEFAULTS["jitter_ms_max"]
        ):
            warns.append(
                f"Jitter hoch: {jitter:.0f} ms (> {SPEEDTEST_WARN_DEFAULTS['jitter_ms_max']:.0f})"
            )
        return warns

    def speedtest_async(self):
        def job():
            self.log_safe("Speedtest gestartet...")
            result, err = run_speedtest(run_cmd, has_cmd, timeout=120)
            if err:
                self.log_safe(f"Speedtest fehlgeschlagen: {err}")
                marker = "Versuchte Befehle:"
                if marker in str(err):
                    attempted = str(err).split(marker, 1)[1].strip()
                    if attempted:
                        self.log_safe(f"Speedtest-Diagnose (CLI): {attempted}")
                return

            self._append_speedtest_history(result)
            self.after(0, lambda r=dict(result): self.update_speedtest_panel(r))
            self.log_debug_safe(json.dumps(result, ensure_ascii=False))
            self.log_debug_safe(format_speedtest_summary(result))
            self.log_debug_safe(format_speedtest_table(result))
            self.log_safe("Speedtest abgeschlossen.")

            for warn in self._speedtest_warn_messages(result):
                self.log_debug_safe(f"[WARN] Speedtest: {warn}")

            if getattr(self, "debug_mode", False):
                self.log_debug_safe(
                    f"Speedtest intern: tool={result.get('tool','-')} history={len(self.speedtest_history)}"
                )

        threading.Thread(target=job, daemon=True).start()

    def update_speedtest_panel(self, result):
        if not result:
            self.speedtest_ping_var.set("-")
            self.speedtest_jitter_var.set("-")
            self.speedtest_download_var.set("-")
            self.speedtest_upload_var.set("-")
            self.speedtest_timestamp_var.set("Noch kein Speedtest durchgeführt")
            return

        ping = result.get("ping_ms")
        jitter = result.get("jitter_ms")
        download = result.get("download_mbps")
        upload = result.get("upload_mbps")
        timestamp = result.get("timestamp")

        self.speedtest_ping_var.set(f"{round(ping)} ms" if ping is not None else "-")
        self.speedtest_jitter_var.set(
            f"{round(jitter)} ms" if jitter is not None else "-"
        )
        self.speedtest_download_var.set(
            f"{download:.1f} Mbit/s" if download is not None else "-"
        )
        self.speedtest_upload_var.set(
            f"{upload:.1f} Mbit/s" if upload is not None else "-"
        )
        self.speedtest_timestamp_var.set(timestamp or "-")

    def show_speedtest_history(self):
        if not self.speedtest_history:
            self.log("Speedtest-Verlauf: noch keine Einträge.")
            return

        self.log("Speedtest-Verlauf (letzte Ergebnisse):")
        for item in self.speedtest_history[-self.speedtest_history_limit :]:
            stamp = item.get("timestamp") or "-"
            ping = item.get("ping_ms")
            jitter = item.get("jitter_ms")
            download = item.get("download_mbps")
            upload = item.get("upload_mbps")

            ping_txt = "-" if ping is None else f"{ping:.0f}"
            jitter_txt = "-" if jitter is None else f"{jitter:.0f}"
            dl_txt = "-" if download is None else f"{download:.1f}"
            ul_txt = "-" if upload is None else f"{upload:.1f}"
            self.log(
                f"{stamp} | Ping {ping_txt} ms | Jitter {jitter_txt} ms | DL {dl_txt} | UL {ul_txt}"
            )

    # ---------- Trace (Table of hops) ----------
    def _hop_lookup_log_once(self, ip: str, message: str):
        key = f"{ip}:{message}"
        if key in self.hop_lookup_warned_ips:
            return
        self.hop_lookup_warned_ips.add(key)
        try:
            self.after(0, lambda m=message: self.log(m))
        except RuntimeError:
            pass

    def hop_lookup(self, ip: str, enabled=None):
        ip = (ip or "").strip()
        if not ip or ip == "*" or ":" in ip:
            return "-", "unbekannt"

        if ip in self.hop_cache:
            return self.hop_cache[ip]

        lookup_enabled = self.hop_lookup_enabled.get() if enabled is None else enabled
        if not lookup_enabled:
            return "-", "-"

        rc, out = run_cmd(
            ["curl", "-s", "--max-time", "3", f"https://ipwho.is/{ip}"], timeout=5
        )
        if rc != 0 or not out:
            self.hop_cache[ip] = ("-", "unbekannt")
            self._hop_lookup_log_once(
                ip,
                f"Hop Lookup: keine Daten für {ip} (Netzwerk/Timeout).",
            )
            return self.hop_cache[ip]

        try:
            data = json.loads(out)
            if not data.get("success", True):
                self.hop_cache[ip] = ("-", "unbekannt")
                msg = (data.get("message") or "").strip()
                if msg:
                    self._hop_lookup_log_once(ip, f"Hop Lookup: {ip} -> {msg}")
                return self.hop_cache[ip]

            cc = (data.get("country_code") or data.get("country") or "").strip()
            org = (
                data.get("org")
                or data.get("connection", {}).get("org")
                or data.get("connection", {}).get("isp")
                or ""
            ).strip()
            if not cc:
                cc = "-"
            if not org:
                org = "unbekannt"
            self.hop_cache[ip] = (cc, org)
            return cc, org
        except Exception:
            self.hop_cache[ip] = ("-", "unbekannt")
            self._hop_lookup_log_once(ip, f"Hop Lookup: ungültige Antwort für {ip}.")
            return self.hop_cache[ip]

    def trace_table_async(self):
        target = (self.trace_target.get() or "").strip()
        lookup_enabled = bool(self.hop_lookup_enabled.get())
        if not target:
            self.log(
                self.tr("trace_log_enter_target", "Bitte Ziel für Trace eingeben.")
            )
            return
        if not is_safe_trace_target(target):
            self.log(
                self.tr(
                    "trace_log_invalid_target",
                    "Trace-Ziel ungültig/unsicher. Erlaubt: IP oder Hostname (ohne Sonderzeichen/Leerzeichen).",
                )
            )
            return
        if not has_cmd("traceroute"):
            self.log(
                self.tr(
                    "trace_log_traceroute_missing",
                    "Für Hops-Tabelle wird 'traceroute' benötigt (sudo apt install traceroute).",
                )
            )
            return

        def clear_table():
            for item in self.trace_table.get_children():
                self.trace_table.delete(item)

        def job():
            self.after(
                0,
                lambda: (
                    self.nb.select(self.tab_trace),
                    clear_table(),
                    self.log(
                        self.tr(
                            "trace_log_started",
                            "Traceroute zu {target} gestartet",
                        ).format(target=target)
                    ),
                ),
            )
            rc, out = run_cmd(
                ["traceroute", "-n", "-q", "1", "-m", "20", target], timeout=35
            )
            hops = parse_traceroute_hops(out)
            rows = []
            for h in hops:
                rtt = "" if h["rtt_ms"] is None else f"{h['rtt_ms']:.2f}"
                cc, org = self.hop_lookup(h["ip"], enabled=lookup_enabled)
                rows.append((h["hop"], h["ip"], rtt, cc or "-", org or "unbekannt"))

            def fill():
                self.nb.select(self.tab_trace)
                if not out.strip():
                    self.log(
                        self.tr(
                            "trace_log_finished_no_output",
                            "Traceroute zu {target} ohne Ausgabe beendet",
                        ).format(target=target)
                    )
                    return
                if rc != 0:
                    self.log(
                        self.tr(
                            "trace_log_finished_rc",
                            "Traceroute zu {target} abgeschlossen mit rc={rc}",
                        ).format(target=target, rc=rc)
                    )
                else:
                    self.log(
                        self.tr(
                            "trace_log_finished",
                            "Traceroute zu {target} abgeschlossen",
                        ).format(target=target)
                    )

                for row in rows:
                    self.trace_table.insert("", "end", values=row)

                if rc != 0 and not rows:
                    self.log(
                        self.tr(
                            "trace_log_no_hops",
                            "Traceroute lieferte keine auswertbaren Hops.",
                        )
                    )

            self.after(0, fill)

        threading.Thread(target=job, daemon=True).start()

